globalThis.KENGURU_LEGACY_CONDITIONS = {"2001":{"1":{"question":"Кенгуру складывает двести сотен и один. Подскажите правильный ответ.","choices":["201","1201","2001","20001","200001"]},"2":{"question":"На четырех рисунках изображены цифры от 1 до 4 вместе со своими зеркальными изображениями. Каким будет следующий рисунок?","image":"assets/legacy-conditions/2001/manual-02.webp","imageWidth":673,"imageHeight":171},"3":{"question":"У Йозефа было 7 палочек. Он разломал одну из них пополам. Сколько теперь у него палочек?","choices":["5","6","7","8","9"]},"4":{"question":"Катя написала фразу «Я люблю решать задачи», подсчитала количество букв в каждом слове и перемножила полученные числа. Какой результат должен был получиться?","choices":["18","30","36","150","180"]},"5":{"question":"Петя и Аня отмечают свой день рождения 16 марта, но Петя родился, когда Ане исполнилось 3 года. Сколько лет будет Пете, когда Аня будет вдвое его старше?","choices":["1 год","2 года","3 года","4 года","10 лет"]},"6":{"question":"Каких геометрических фигур нет на рисунке?","choices":["прямоугольников","треугольников","квадратов","кругов","все эти фигуры есть"],"image":"assets/legacy-conditions/2001/task-06.webp","imageWidth":411,"imageHeight":513},"7":{"question":"С какой скоростью школьник Вова может идти из школы домой?","image":"assets/legacy-conditions/2001/task-07.webp","imageWidth":933,"imageHeight":64},"8":{"question":"Во дворе школы играют 19 девочек и 12 мальчиков. Какое количество ребят должно к ним присоединиться, чтобы все они могли разбиться на 6 равных команд?","choices":["1","2","3","4","5"]},"9":{"question":"Джимми купил в подарок своей маме шоколадное сердечко. Сколько весит эта шоколадка, если каждый квадратик весит 10 г?","choices":["340 г","360 г","380 г","400 г","420 г"],"image":"assets/legacy-conditions/2001/task-09.svg","imageWidth":220,"imageHeight":218},"10":{"question":"В магазин обуви пришли 4 сороконожки в одинаковых башмачках (у каждой из них по 20 пар ног). У одной из сороконожек не хватало обуви на задней половине ног, у другой – на передней половине, у третьей обуты были только правые ножки, а у четвертой − только левые. Они купили в магазине обувь и ушли полностью обутые. Сколько пар обуви купили сороконожки в магазине?","choices":["10","20","40","60","80"]},"11":{"question":"Вика завязала бантик над правым ухом и вертится пред зеркалом. Сколько из следующих изображений можно увидеть в зеркале?","choices":["0","1","2","3","4"],"image":"assets/legacy-conditions/2001/task-11.webp","imageWidth":915,"imageHeight":195},"12":{"question":"Нескольким кенгуру раздали 50 яблок так, чтобы каждый кенгуру получил хотя бы по одному яблоку и ни у каких двух кенгуру не было поровну яблок. Какое наибольшее количество кенгуру могли получить яблоки?","choices":["10","9","8","6","5"]},"13":{"question":"Бетти и Кетти путешествуют на суперпоезде. Бетти едет в сто семнадцатом вагоне с начала поезда, а Кетти – в сто тридцать четвертом с конца. Оказалось, что они едут в соседних вагонах. Сколько вагонов могло быть в поезде?","image":"assets/legacy-conditions/2001/task-13.webp","imageWidth":731,"imageHeight":75},"14":{"question":"На каком из следующих рисунков изображена фигура не такая, как на остальных?","image":"assets/legacy-conditions/2001/manual-14.webp","imageWidth":735,"imageHeight":119},"15":{"question":"Пятеро друзей выясняли, какой сегодня день недели. Андрей сказал: «Позавчера была пятница». Володя сказал: «Послезавтра будет вторник». Сережа сказал: «Вчера была суббота». Дима сказал: «Завтра будет понедельник». Егор сказал: «Сегодня четверг». Один их них ошибся. Кто?","choices":["Андрей","Володя","Сережа","Дима","Егор"]},"16":{"question":"На столе лежат пятиугольники и шестиугольники. Всего у них ровно 37 вершин. Сколько пятиугольников на столе?","choices":["1","2","3","4","5"]},"17":{"question":"Четырехзначное число начинается с цифры 5. Эту цифру переставили в конец числа. Полученное число оказалось на 747 меньше исходного. Какова сумма цифр этого числа?","choices":["12","14","16","18","20"]},"18":{"question":"В ряд стоят три коробки, в каждой по 11 конфет. Я беру по одной конфете из каждой коробки в таком порядке: левая, центральная, правая, центральная, левая, центральная, и так далее до тех пор, пока в центральной коробке не закончатся конфеты. В одной из двух крайних коробок осталось больше конфет. Сколько?","choices":["1","2","5","6","11"]},"19":{"question":"На игральном кубике общее число точек на любых двух противоположных гранях равно 7. Дженни склеила столбик из 6 таких кубиков и подсчитала общее число точек на всех наружных гранях. Какое самое большое число она могла получить?","choices":["106","96","95","91","84"]},"20":{"question":"Сколько существует трехзначных чисел, у которых сумма цифр равна 4?","choices":["10","9","8","7","6"]},"21":{"question":"Какое самое маленькое число спичек можно добавить к этой фигуре, чтобы получить точно 11 квадратов?","choices":["2","3","4","5","6"],"image":"assets/legacy-conditions/2001/manual-21.webp","imageWidth":192,"imageHeight":188},"22":{"question":"Есть 6 карточек с цифрами 1, 2, 3, 4, 5 и 6. Используя их, можно составить два трехзначных числа, например, 645 и 321. Вася составил эти числа так, что их разность оказалась самой маленькой из всех возможных. Эта разность равна","choices":["89","69","56","47","38"]},"23":{"question":"Кубик лежит на листе бумаги в клетку, как показано на рисунке. Кубик перекатывают через ребра в направлениях, указанных стрелочками. Сколько точек окажется сверху, когда кубик попадет на клетку, отмеченную звездочкой?","choices":["1","2","3","4","другой ответ"],"image":"assets/legacy-conditions/2001/task-23.webp","imageWidth":379,"imageHeight":190},"24":{"question":"Какие два из нарисованных восьмиугольников раскрашены одинаково?","choices":["3 и 6","2 и 6","1 и 3","4 и 6","5 и 2"],"image":"assets/legacy-conditions/2001/task-24.webp","imageWidth":905,"imageHeight":191},"25":{"question":"Про число a известно, что его последняя цифра равна 1, и что оно делится ровно на десять различных чисел (включая 1 и a). На сколько различных чисел делится число 10a?","choices":["20","30","40","50","100"]},"26":{"question":"Три черепахи – Анди, Банди и Канди – соревнуются в беге на дистанцию 30 м. Они стартовали одновременно. Когда Анди финишировала, Банди оставалось до финиша 10 м, а Канди была на 4 м впереди Банди. На каком расстоянии до финиша будет Банди, когда Канди закончит дистанцию, если каждая черепаха движется с постоянной скоростью?","choices":["2 м","3 м","4 м","5 м","6 м"]}},"2002":{"1":{"question":"Какой из следующих квадратиков вырезан из картинки, изображенной справа?","image":"assets/legacy-conditions/2002/task-01.webp","imageWidth":938,"imageHeight":220},"3":{"question":"На одной чашке весов лежат 6 апельсинов, а на другой — 2 дыни. Если добавить одну такую же дыню к апельсинам, то весы будут уравновешены. Значит, дыня весит столько же, сколько","choices":["2 апельсина","3 апельсина","4 апельсина","5 апельсинов","6 апельсинов"]},"4":{"question":"Джозеф живет на улице, дома на которой имеют номера с 1 по 24. Сколько раз при написании этих номеров используется цифра 2?","choices":["2","4","8","16","325"]},"5":{"question":"Таня видит из окна флаг, который развевается на ветру. Флаг имеет форму прямоугольника. Какую из картинок Таня не могла увидеть?","image":"assets/legacy-conditions/2002/manual-05.webp","imageWidth":675,"imageHeight":227},"6":{"question":"Прибавив 17 к самому маленькому двузначному числу и разделив эту сумму на самое большое однозначное число, мы получим","choices":["3","6","9","11","27"]},"7":{"question":"В каком из этих ожерелий ровно две трети камушков темные?","image":"assets/legacy-conditions/2002/task-07.webp","imageWidth":864,"imageHeight":125},"8":{"question":"Если в этом году на следующий день после своего дня рождения я скажу: «Послезавтра будет среда», то это будет правильно. В какой день недели у меня день рождения в этом году?","choices":["в четверг","в понедельник","во вторник","в среду","в воскресенье"]},"9":{"question":"В Месопотамии за 2500 лет до нашей эры единицы обозначали значком ∆, десятки – значком ◄, а число шестьдесят – значком ▼. Как записывалось число 124?","choices":["◄▼▼∆∆∆∆","▼▼◄◄∆∆∆∆","▼◄◄∆∆∆∆","▼∆∆∆◄◄▼","▼▼∆∆∆∆"]},"10":{"question":"В 9-00 большой старый будильник поставили правильно. Но он отстает на 1 минуту в час. Тогда","choices":["в 10-00 он покажет 9-59","в 10-00 он покажет 10-01","в 9-59 он покажет 10-00","в 11-00 он покажет 10-59","в 10-10 он покажет 10-09"]},"11":{"question":"Число x таково, что прибавить к нему 2 — то же самое, что умножить его на 3. Тогда умножить его на 6 — это то же самое, что прибавить к нему","choices":["3","4","5","6","7"]},"12":{"question":"У каждого из четырех ребят живет какое-то одно любимое животное: кошка, собака, рыбка или канарейка (у всех разные). У Манон животное – с пушистой шерстью, у Фабиана – четвероногое, у Николя – пернатое. И Жюли, и Манон не любят кошек. Какое из следующих утверждений неверно?","choices":["У Фабиана – собака","У Николя – канарейка","У Фабиана – кошка","У Жюли – рыбка","У Манон – собака"]},"13":{"question":"На рисунке мы видим разломанные циферблаты часов. Часовых дел мастер подсчитал суммы чисел на всех обломках. Оказалось, что для одного из циферблатов эти суммы – четыре последовательных числа. Какой это циферблат?","image":"assets/legacy-conditions/2002/task-13.webp","imageWidth":949,"imageHeight":213},"14":{"question":"ABCD — квадрат со стороной 10 см, а AMTD — прямоугольник. Его короткая сторона равна 3 см. На сколько периметр квадрата больше, чем периметр прямоугольника AMTD?","choices":["14 см","10 см","7 см","6 см","4 см"],"image":"assets/legacy-conditions/2002/manual-14.webp","imageWidth":159,"imageHeight":160},"15":{"question":"В букете 11 цветов, причем 5 из них — красные, а 6 — розы. Какое наибольшее число белых гвоздик может быть в букете?","choices":["4","5","6","7","8"]},"16":{"question":"Маша вышла из дома в 7 час 55 мин и пришла в школу в 8 час 32 мин. Ее подруга Даша пришла в школу только в 8 час 45 мин, хотя она живет ближе к школе и ей требуется на дорогу на 12 минут меньше, чем Маше. Когда Даша вышла из дома?","choices":["в 8 час 7 мин","в 8 час 20 мин","в 8 час 25 мин","в 8 час 30мин","в 8 час 33 мин"]},"17":{"question":"Сначала Роберт построил из всех своих одинаковых кубиков тоннель. Потом он разобрал тоннель и построил пирамиду. Сколько лишних кубиков осталось у Роберта?","choices":["34","29","22","18","15"],"image":"assets/legacy-conditions/2002/task-17.webp","imageWidth":342,"imageHeight":168},"18":{"question":"На доске в строчку написаны двадцать пятерок. Поставив между некоторыми из них знак «+», Вася обнаружил, что сумма равна 1000. Сколько плюсов поставил Вася?","choices":["6","8","9","10","11"]},"19":{"question":"В зоопарке Санкт-Петербурга жили 3 кенгуру: Лиззи, Дженни и Бином. А потом родился крошка Ру. Сейчас все это семейство съедает 28 кг морковки в неделю, причем Ру съедает ровно вдвое меньше, чем любой из старших кенгуру. Сколько морковки в неделю съедало это семейство до рождения Ру?","choices":["14 кг","12 кг","20 кг","24 кг","11 кг"]},"20":{"question":"Лиса Алиса и кот Базилио пришли в харчевню «Трех пескарей», заказали обед и дали хозяину 10 золотых. Тот в качестве сдачи вернул им столько денег, сколько стоил обед. Лиса заметила, что хозяин дал им на 2 золотых меньше, чем нужно. Сколько денег он должен был вернуть им на самом деле?","choices":["4","5","6","7","другой ответ"]},"21":{"question":"Трое ребят разделили между собой карточки с цифрами. Алексу достались цифры 7, 2 и 4, Марте – 6, 5 и 1, а Фреду – 8, 3 и 9. Каждый из них старается получить разные числа, используя свои карточки и знаки четырех арифметических действий. Кто из них не может получить число 20?","choices":["Алекс","Марта","Фред","Алекс и Марта","все могут"]},"22":{"question":"В слове КЕНГУРУ каждая буква обозначает какую-то цифру (разные буквы обозначают разные цифры, а одинаковые буквы – одинаковые цифры). Какое самое большое количество нечетных цифр может оказаться в числе КЕНГУРУ+КЕНГУРУ?","choices":["3","4","5","6","7"],"image":"assets/legacy-conditions/2002/task-22.webp","imageWidth":548,"imageHeight":235},"23":{"question":"Ваня играет в компьютерную игру. Сначала перед ним на экране 5 красных и 7 синих шариков. За один ход разрешается заменить какие-то три шарика одного цвета на два шарика другого цвета. Ваня хочет создать следующие картинки: 1 синий и 1 красный шарик, либо 9 красных и 1 синий, либо 9 синих и 1 красный, либо 2 синих. Сколько из этих картинок можно получить в такой игре?","choices":["0","1","2","3","4"]},"24":{"question":"В автомобильных гонках участвовали три машины. Они стартовали в таком порядке: Я, Ф, К, то есть сначала «Ягуар», потом «Феррари», потом «Кенгуру». На дистанции «Ягуар» обогнали 3 раза, «Феррари» – 5 раз, а «Кенгуру» – 8 раз. В каком порядке машины пришли к финишу?","choices":["Ф, К, Я","Я, К, Ф","К, Ф, Я","Я, Ф, К","нельзя определить"]},"25":{"question":"Все числа от 1 до 7 вписывают по одному в кружки на рисунке так, чтобы суммы чисел в каждой тройке кружков, расположенных на прямой линии, были одинаковыми. Сколько существует способов заполнить центральный кружок?","choices":["0","1","2","3","7"],"image":"assets/legacy-conditions/2002/task-25.webp","imageWidth":252,"imageHeight":218},"26":{"question":"Алиса и Белый Кролик в полдень вместе вышли из домика Кролика и пошли на прием к Герцогине. Пройдя полпути, Кролик вспомнил, что забыл перчатки и веер, и вернулся за ними домой. В результате Алиса пришла к Герцогине за 5 минут до начала приема, а Кролик опоздал на 10 минут. Алиса и Кролик шли с постоянными и одинаковыми скоростями. На какое время был назначен прием у Герцогини?","choices":["12-10","12-15","12-20","12-25","12-30"]}},"2003":{"1":{"question":"Софи рисует цветных кенгуру: сначала голубого, потом красного, потом черного, потом желтого, снова голубого, красного, черного, желтого и так далее. Какого цвета будет семнадцатый кенгуру?","choices":["голубого","зеленого","красного","черного","желтого"]},"2":{"question":"Число 0 + 1 + 2 + 3 + 4 − 3 − 2 − 1 − 0 равно","choices":["0","2","4","10","16"]},"3":{"question":"На какой картинке сердечки составляют ровно три четверти от общего числа фигурок?","image":"assets/legacy-conditions/2003/task-03.webp","imageWidth":779,"imageHeight":175},"4":{"question":"Если бы выходными днями в сентябре были все числа, в которых есть четные цифры, то в школу в сентябре пришлось бы ходить","choices":["9 дней","10 дней","11 дней","12 дней","15 дней"]},"5":{"question":"Васиного отца зовут Иван Николаевич, а дедушку — Семен Петрович. Каково отчество Васиной мамы?","choices":["Ивановна","Николаевна","Семеновна","Петровна","Васильевна"]},"6":{"question":"Лист бумаги сложили и разрезали, как показано на рисунке. Сколько кусочков получилось?","choices":["2","3","4","5","6"],"image":"assets/legacy-conditions/2003/task-06.svg","imageWidth":220,"imageHeight":188},"7":{"question":"Самое маленькое целое число, которое делится на 2, 3 и 4, равно","choices":["1","2","6","12","24"]},"8":{"question":"Пятачок посадил 8 желудей. Из всех желудей, кроме двух, выросли дубы. На всех дубах, кроме двух, растут желуди. Желуди со всех плодоносящих дубов, кроме одного, — невкусные. Значит, число дубов с невкусными желудями равно","choices":["0","1","2","3","4"]},"9":{"question":"В прямоугольнике 4×7, нарисованном на клетчатой бумаге, провели диагональ. Сколько клеточек она разрезала?","choices":["8","9","10","11","12"]},"10":{"question":"Выписав 6 четных чисел, идущих подряд, Вася обнаружил, что самое большое из них вдвое больше самого маленького. Чему равно самое маленькое число?","choices":["4","6","8","10","12"]},"11":{"question":"Как-то в воскресенье, в 9 часов 30 минут утра, Аня присела поиграть в компьютерную игру, но заигралась, и мама прогнала ее от компьютера только днем, в 3 часа 15 минут. В следующее воскресенье ее брат Мартин ухитрился просидеть за компьютером еще на 1 час 50 минут дольше. Сколько времени провел у компьютера Мартин?","choices":["6 час 30 мин","6 час 35 мин","7 час 35 мин","10 час 15 мин","3 часа"]},"12":{"question":"Сколько треугольников на рисунке имеют такую же площадь, как и целая клетка?","choices":["5","6","7","8","другой ответ"],"image":"assets/legacy-conditions/2003/task-12.svg","imageWidth":228,"imageHeight":175},"13":{"question":"На заседании присутствуют 29 академиков, 12 из них имеют бороду, а 18 — усы. У трех академиков нет ни бороды, ни усов. Сколько академиков имеют и бороду, и усы?","choices":["4","5","6","11","16"]},"14":{"question":"Штрих-код образован 17 черными и белыми полосками (крайние полоски — черные). Черные полоски бывают двух типов: узкие и широкие. Число белых полосок на 3 больше, чем число широких черных. Чему равно число узких черных полосок?","choices":["1","2","3","4","5"],"image":"assets/legacy-conditions/2003/task-14.svg","imageWidth":220,"imageHeight":127},"15":{"question":"Кенгуру купил конфеты трех видов: большие, маленькие и средние. Каждая большая конфета стоит 4 монеты, средняя — 2 монеты и маленькая — 1 монету. За 10 конфет Кенгуру заплатил 16 монет. Сколько больших конфет он купил?","choices":["5","4","3","2","1"]},"16":{"question":"Чему равна площадь буквы N, если площадь клетки равна 1?","choices":["14","15","16","17","18"],"image":"assets/legacy-conditions/2003/task-16.svg","imageWidth":206,"imageHeight":220},"17":{"question":"Сережа любит подсчитывать сумму цифр на табло электронных часов. Например, если часы показывают 21:17, он получает сумму 11. Какую наибольшую сумму он может получить?","choices":["19","23","24","25","36"]},"18":{"question":"Сколько страниц в книжке, если для того, чтобы их пронумеровать, понадобилось всего 35 цифр?","choices":["17","18","22","24","35"]},"19":{"question":"Какое наибольшее число веревочек можно разрезать на этой сетке, чтобы она не распалась на куски? (Разрезать по узелкам сетки нельзя!)","choices":["7","8","9","10","11"],"image":"assets/legacy-conditions/2003/manual-19.webp","imageWidth":160,"imageHeight":152},"20":{"question":"Во сколько раз увеличится трехзначное число, если написать его два раза подряд?","choices":["2","100","101","1000","1001"]},"21":{"question":"Брусок собран из трех деталей. Каждая деталь состоит из четырех кубиков и окрашена в свой цвет. Как выглядит белая деталь?","image":"assets/legacy-conditions/2003/task-21.webp","imageWidth":944,"imageHeight":384},"22":{"question":"Маша старше Миши ровно на один месяц (дни их рождения приходятся на одно и то же число в двух соседних месяцах), а Даша старше Миши на столько же дней, на сколько Маша старше Даши. В каком месяце не могла родиться Даша?","choices":["в апреле","в мае","в июле","в августе","в декабре"]},"23":{"question":"В десятичной записи числа 79865 использованы 5 последовательных цифр. Чему равна третья цифра следующего пятизначного числа, обладающего таким же свойством?","choices":["4","5","6","7","другой ответ"]},"24":{"question":"После того, как из мозаики вынули две фигурки, составленные из ее элементов, образовалась «дырка» (см. рисунок). Какие фигурки вынули?","choices":["1 и 4","2 и 4","2 и 3","1 и 3","3 и 4"],"image":"assets/legacy-conditions/2003/task-24.webp","imageWidth":820,"imageHeight":192},"25":{"question":"Вася изменяет число, написанное на доске, по следующему правилу: если это число делится на 3, то Вася вычитает из него 1; если число дает остаток 2 при делении на 3, то Вася вычитает из него 2; а если число дает остаток 1, то Вася прибавляет к нему 2. Он начинает с числа 10000. Какое число получит Вася после 2003 таких операций?","choices":["10000","7004","7002","6999","3996"]},"26":{"question":"Четыре девочки поют песни, аккомпанируя друг другу по очереди: каждый раз одна из них играет, остальные три поют. Оказалось, что Анна спела больше всех песен – восемь, а Дороти спела меньше всех – пять. Сколько всего песен спели девочки?","choices":["12","11","10","9","невозможно определить"]}},"2004":{"1":{"question":"У Гарри Поттера есть волшебные очки, в которых он видит все красное — белым, а все белое — красным. Гарри посмотрел через свои волшебные очки на прямоугольник, изображенный справа. Что он увидел?","image":"assets/legacy-conditions/2004/task-01.webp","imageWidth":930,"imageHeight":310},"2":{"question":"Чему равна сумма двух чисел, если она на 3 больше одного из этих чисел и на 4 больше другого?","choices":["3","4","5","7","14"]},"3":{"question":"На участке дороги идет ремонт. Водителям приходится объезжать этот участок по запасному пути, отмеченному на плане пунктиром. На сколько километров увеличивает путь этот объезд?","choices":["3 км","5 км","6 км","10 км","невозможно определить"],"image":"assets/legacy-conditions/2004/task-03.webp","imageWidth":348,"imageHeight":143},"4":{"question":"Сережа шел по лестнице, шагая через ступеньку (первую ступеньку он пропустил). При этом он считал шаги: «Один, два, три…». После того, как он сказал «пять», оказалось, что осталась одна ступенька. Сколько всего ступенек на лестнице?","choices":["5","7","9","11","12"]},"5":{"question":"Какие числа расположены одновременно в прямоугольнике и в круге, но не в треугольнике?","choices":["5 и 11","1 и 10","13","3 и 9","6,7 и 4"],"image":"assets/legacy-conditions/2004/task-05.webp","imageWidth":313,"imageHeight":271},"6":{"question":"Какое число пропущено: 2004 – 1389 = … – 1489?","choices":["1994","1995","2104","615","1904"]},"7":{"question":"Миша хочет обвести каждую из фигур А – Е фломастером, не отрывая фломастер от листа бумаги и не проводя по одной линии дважды. Какую фигуру он не сможет так обвести?","image":"assets/legacy-conditions/2004/task-07.webp","imageWidth":812,"imageHeight":131},"8":{"question":"Разглядывая семейный альбом, Ванечка нашел там фотографии своих двух бабушек и двух дедушек. А сколько бабушек и дедушек имели его бабушки и дедушки все вместе?","choices":["4","8","10","16","32"]},"9":{"question":"Какие фигурки надо взять, чтобы из них можно было составить круг?","image":"assets/legacy-conditions/2004/task-09.webp","imageWidth":912,"imageHeight":201},"10":{"question":"В коридоре детского сада стояли двухколесные и трехколесные велосипеды. Катя подсчитала, что колес – 18, а рулей всего 7. Сколько было двухколесных велосипедов?","choices":["2","3","4","5","6"]},"11":{"question":"Весь класс, в котором учатся Маша и Даша, выстроился в колонну по одному. Позади Маши стоит 16 человек, включая Дашу, а впереди Даши стоит 14 человек. Сколько ребят в классе, если между Машей и Дашей стоит 7 человек?","choices":["37","30","23","22","365"]},"12":{"question":"Часовщик смотрит на 4 будильника. Только один из этих будильников показывает верное время. Из оставшихся один спешит на 20 минут, другой отстает на 20 минут, а третий вовсе стоит. Какое время показывает правильно идущий будильник?","choices":["4 час 45 мин","5 час 5 мин","5 час 25 мин","5 час 40 мин","невозможно определить"],"image":"assets/legacy-conditions/2004/task-12.webp","imageWidth":815,"imageHeight":169},"13":{"question":"В некотором месяце 3 воскресенья приходятся на четные числа. На какой день недели приходится 25-е число этого месяца?","choices":["вторник","среда","четверг","пятница","суббота"]},"14":{"question":"Карина нашла старую книгу, в которой не хватало нескольких страниц. Последняя страница перед потерянной частью имеет номер 24, а первая после нее – 45. Сколько листков выпало из книги?","choices":["9","10","11","20","21"]},"15":{"question":"В каждую клеточку квадрата 2х2 вписано какое-то число. Сумма чисел в верхней строчке равна 3, а в нижней – 8. Чему равна сумма в правом столбике, если сумма чисел левого столбика равна 4?","choices":["4","6","7","8","11"],"image":"assets/legacy-conditions/2004/task-15.svg","imageWidth":220,"imageHeight":220},"16":{"question":"Во сколько раз миллион миллиардов отличается от миллиарда миллионов?","choices":["в миллион раз больше","в миллиард раз больше","в тысячу раз меньше","эти числа равны","в сто раз меньше"]},"17":{"question":"У Эдварда 2004 фантика. Половина из них синие, четверть – красные, третья часть остальных – зеленые. Сколько у него зеленых фантиков?","choices":["0","167","501","668","1002"]},"18":{"question":"На каждой грани бумажного кубика написана цифра 1, 2 или 3, причем цифры на противоположных гранях одинаковы. Какая из фигурок может получиться, если этот кубик разрезать по некоторым ребрам и развернуть?","image":"assets/legacy-conditions/2004/task-18.webp","imageWidth":945,"imageHeight":164},"19":{"question":"В полдень на детскую площадку пришел Вася, через два часа после него – Маша, а через полтора часа после нее – Никита. Вася играл четыре часа, Маша – три, а Никита – два часа. Как долго Маша и Никита были на площадке вдвоем?","choices":["полчаса","один час","полтора часа","два часа","три часа"]},"20":{"question":"Два ковша воды — это половина ведерка, а три чашки — это половина ковша. Тогда два ведерка — это","choices":["24 чашки","48 чашек","12 чашек","36 чашек","72 чашки"]},"21":{"question":"В трех играх чемпионата по футболу команда забила 3 гола и пропустила в свои ворота 1 гол. За каждую победу команда получает 3 очка, за ничью – 1 очко, а за поражение — 0 очков. Сколько очков не могла набрать команда за эти 3 игры?","choices":["7","6","5","4","3"]},"22":{"question":"В верхнюю строчку и первый столбец квадратной таблицы (кроме угловой клетки) записали какието числа, и для этих чисел составили таблицу умножения. Потом некоторые числа стерли, а некоторые заменили буквами. Какие две буквы заменяют одно и то же число?","choices":["Е и Н","Р и У","Т и А","Е и Я","Г и А"],"image":"assets/legacy-conditions/2004/task-22.svg","imageWidth":230,"imageHeight":229},"23":{"question":"Длинную нитку сложили вдвое, еще раз вдвое и еще раз вдвое. Получившуюся толстую «нитку» разрезали на две части и разобрали обратно на тонкие ниточки. Оказалось, что две из этих ниточек имеют длины 4 см и 9 см. Какова наименьшая возможная длина исходной нитки?","choices":["48 см","52 см","56 см","64 см","68 см"]},"24":{"question":"Каждая из фигурок А – D состоит из 7 кубиков. Какую из них нельзя составить из деталей, изображенных справа?","image":"assets/legacy-conditions/2004/task-24.webp","imageWidth":954,"imageHeight":339},"25":{"question":"В треугольнике отмечены вершины и, кроме того, по одной точке на каждой из сторон. Сколько треугольников с вершинами в отмеченных точках можно построить?","choices":["5","10","17","20","21"],"image":"assets/legacy-conditions/2004/task-25.webp","imageWidth":259,"imageHeight":194},"26":{"question":"Разность двух четырехзначных чисел равна 7. Для каждого из этих чисел Вася вычислил сумму цифр, а потом из большей суммы вычел меньшую. Какой результат он не мог получить?","choices":["2","7","11","13","20"]}},"2005":{"1":{"question":"В этом году ежегодный конкурс «Кенгуру» проводится в России уже в 12-й раз. В каком году был первый конкурс?","choices":["1993","1994","1995","1894","994"]},"2":{"question":"Общий вес троих детей 72 кг. Маша весит столько же, сколько два ее младших брата вместе. Сколько весит Маша?","choices":["18 кг","24 кг","32 кг","36 кг","52 кг"]},"4":{"question":"В магазин привезли 4 одинаковые полные коробки: в одной – апельсины, в другой – яблоки, в третьей – мандарины, в четвертой – вишни. В какой коробке наибольшее число плодов?","image":"assets/legacy-conditions/2005/task-04.webp","imageWidth":903,"imageHeight":124},"5":{"question":"Бабочка села на число в правой части верного равенства 2005 − 205 = 1300 + □. Какое число она закрыла?","choices":["250","400","500","705","1800"]},"6":{"question":"Какое из чисел обладает такими свойствами: оно четное, все его цифры различны, а число сотен в два раза больше числа единиц?","choices":["1236","3478","4683","4874","8462"]},"7":{"question":"Квадрат разрезали на 3 кусочка. Два из них изображены на рисунке справа. Укажите третий кусочек.","image":"assets/legacy-conditions/2005/task-07.webp","imageWidth":957,"imageHeight":290},"8":{"question":"В летнем лагере «Кенгуру» Алеша решал по 4 задачи в день, а Андрей – по 2 задачи. Алеша решил все задачи за 5 дней. За сколько дней решил эти же задачи Андрей?","choices":["4","5","6","8","10"]},"9":{"question":"Никита живет в своем доме вместе с папой, мамой и братом. А еще с ними живут собака, две кошки, два попугая и четыре золотые рыбки. Сколько всего ног у обитателей этого дома?","choices":["22","24","28","32","40"]},"10":{"question":"Если одно из чисел увеличить в 20 раз, а другое уменьшить в 10 раз, то произведение этих чисел","choices":["увеличится в 2 раза","уменьшится в 2 раза","увеличится в 20 раз","уменьшится в 20 раз","не изменится"]},"11":{"question":"На столе лежала коробка с конфетами. Саша взял оттуда половину конфет, потом половину оставшихся конфет взял Коля. Затем Света взяла из коробки половину того, что там было. После этого осталось 3 конфеты. Сколько конфет было в коробке сначала?","choices":["6","12","18","24","36"]},"12":{"question":"За один ход Петер поворачивает квадрат с закрашенным треугольником вокруг точки P, как показано на рисунке. В каком положении будет треугольник после 17 ходов?","image":"assets/legacy-conditions/2005/task-12.webp","imageWidth":944,"imageHeight":330},"13":{"question":"У Даши было 9 кусочков бумаги. Некоторые из них она разрезала на три части. Всего получилось 15 кусочков. Сколько кусочков разрезала Даша?","choices":["1","2","3","4","5"]},"14":{"question":"Пять карточек с цифрами лежат на столе в таком порядке: 5, 1, 4, 3, 2. За один ход разрешается поменять местами любые две карточки. За какое наименьшее число ходов можно расположить их в порядке 1, 2, 3, 4, 5?","choices":["2","3","4","5","6"],"image":"assets/legacy-conditions/2005/task-14.webp","imageWidth":254,"imageHeight":170},"15":{"question":"Царь Кащей подобрел и решил потратить 50 золотых монет на подарки детям. В сундуке у него хранится 5 ларцов, в каждом ларце по 3 шкатулки, а в каждой шкатулке по 10 золотых монет. Сундук, ларцы и шкатулки заперты на замки. Какое наименьшее число замков потребуется открыть Кащею, чтобы достать 50 монет?","choices":["5","6","7","8","9"]},"16":{"question":"Из 6 спичек можно сложить только один прямоугольник (он изображен на рисунке). Сколько различных прямоугольников можно сложить, используя каждый раз 14 спичек?","choices":["1","2","3","4","6"],"image":"assets/legacy-conditions/2005/task-16.webp","imageWidth":247,"imageHeight":122},"17":{"question":"Во дворе живут два кота и две собаки. Кот Малыш боится обеих собак, а кот Тоша боится Шарика и дружит с Бобиком. Какое из утверждений неверно?","choices":["Каждый из котов боится какой-то из собак.","Есть кот, который не боится какой-то из собак.","Есть собака, которую боятся оба кота.","Есть собака, которую не боится ни один из котов.","Каждая из двух собак вызывает страх у какого-то из котов."]},"18":{"question":"Какой из кубиков можно склеить из заготовки, изображенной справа?","image":"assets/legacy-conditions/2005/manual-18.webp","imageWidth":518,"imageHeight":360},"19":{"question":"Две девочки и три мальчика вместе съели 16 порций мороженого. Каждый мальчик съел в 2 раза больше порций, чем каждая девочка. Сколько порций съедят 3 девочки и 2 мальчика с такими же аппетитами?","choices":["12","13","14","16","17"]},"20":{"question":"Вокруг прямоугольного сквера проложена дорожка, которая на всем своем протяжении имеет одинаковую ширину. Наружная граница дорожки на 8 м длиннее внутренней. Чему равна ширина дорожки?","choices":["50 cм","1 м","2 м","3 м","4 м"],"image":"assets/legacy-conditions/2005/task-20.webp","imageWidth":284,"imageHeight":171},"21":{"question":"У каждого двузначного числа нашли произведение цифр, потом у каждого такого произведения подсчитали сумму цифр. Какая сумма самая большая?","choices":["9","11","13","15","18"]},"22":{"question":"На этой картинке можно увидеть треугольники и квадраты, причем квадратов меньше, чем треугольников. На сколько?","choices":["1","2","3","4","5"],"image":"assets/legacy-conditions/2005/task-22.svg","imageWidth":220,"imageHeight":217},"23":{"question":"В семье четверо детей, им 5, 8, 13 и 15 лет, а зовут их Таня, Юра, Света и Лена. Одна девочка ходит в детский сад, Таня старше Юры, а сумма лет Тани и Светы делится на три. Сколько лет Лене?","choices":["5","8","13","15","невозможно определить"]},"24":{"question":"Австралийский ленивец Бумми почти всю жизнь проводит на дереве. Однако, если месяц начинается и кончается одним и тем же днем недели, то он слезает с дерева и отправляется путешествовать на весь этот месяц. Сколько месяцев с начала 2005 года по конец 2015 года Бумми проведет в путешествиях?","choices":["1","2","4","12","24"]},"25":{"question":"На белой доске 5×5 Петя закрасил какие-то клетки синим цветом, а какие-то – красным (каждым цветом закрашена хотя бы одна клетка). Никакие две клетки красного и синего цвета не имеют общей стороны. Какое наибольшее число клеток могло быть закрашено?","choices":["25","23","22","21","20"]},"26":{"question":"В числовом ребусе различные значки обозначают различные цифры, а одинаковые значки — одинаковые цифры. Какую наименьшую цифру может обозначать △?","choices":["9","8","6","4","2"],"image":"assets/legacy-conditions/2005/manual-26.webp","imageWidth":139,"imageHeight":127}},"2006":{"1":{"question":"Вася поет слово КЕНГУРУ. Он тянет каждый гласный звук 5 секунд, а на каждый согласный тратит ровно 1 секунду. Сколько времени он поет это слово?","choices":["7 сек","17 сек","19 сек","29 сек","35 сек"]},"2":{"question":"Сколько кубиков вынули?","choices":["4","5","6","7","8"],"image":"assets/legacy-conditions/2006/task-02.webp","imageWidth":421,"imageHeight":152},"3":{"question":"В кошельке у Сергея три монеты: 5 рублей, 2 рубля и 1 рубль. Какую сумму он не сможет заплатить без сдачи?","choices":["3 рубля","4 рубля","6 рублей","7 рублей","8 рублей"]},"4":{"question":"Кенгуру прошел через лабиринт, в котором один вход и пять выходов. Его маршрут проходил только по треугольным комнатам. Где он вышел?","choices":["1","2","3","4","5"],"image":"assets/legacy-conditions/2006/task-04.webp","imageWidth":354,"imageHeight":250},"5":{"question":"У Кати вчера был день рождения. Завтра будет пятница. В какой день недели был день рождения Кати?","choices":["во вторник","в среду","в пятницу","в субботу","в воскресенье"]},"6":{"question":"Шесть городов соединены автобусными маршрутами. Стоимость проезда между этими городами указана на схеме. За какую наименьшую сумму можно проехать из города А в город В?","choices":["70","80","90","100","110"],"image":"assets/legacy-conditions/2006/task-06.webp","imageWidth":359,"imageHeight":176},"7":{"question":"Если уменьшаемое уменьшить на 1, а из вычитаемого вычесть 1, то разность","choices":["не изменится","увеличится на 1","уменьшится на 1","увеличится на 2","уменьшится на 2"]},"8":{"question":"Коля играет на компьютере каждый день по 40 минут, а Вася – по 5 часов в неделю (больше родители не разрешают). Кому из мальчиков за неделю удается больше времени поиграть на компьютере и на сколько?","choices":["Коле больше на 40 минут","Васе больше на 20 минут","Васе больше на 40 минут","Коле больше на 20 минут","поровну"]},"9":{"question":"На каком из квадратиков закрашена ровно одна треть клеточек?","image":"assets/legacy-conditions/2006/task-09.webp","imageWidth":935,"imageHeight":212},"10":{"question":"Петя прибавляет различные однозначные числа к числу 96. Сколько раз он получит трехзначное число?","choices":["3","4","5","6","7"]},"11":{"question":"На левой стороне улицы находятся дома с нечетными номерами от 1 до 19, а на правой стороне – дома с четными номерами от 2 до 14. Сколько домов на этой улице?","choices":["16","17","18","19","33"]},"12":{"question":"За квадратный столик могут сесть одновременно 4 гнома, по одному с каждой стороны. Для вечеринки 7 таких столиков составили в ряд (вплотную один к другому). Сколько гномов могут сесть за получившийся длинный стол?","choices":["14","16","21","24","28"]},"13":{"question":"Самое маленькое число, которое можно получить, выкладывая в ряд карточки, изображенные справа, равно","choices":["2 309 541 768","7 309 568 412","2 741 568 309","2 309 415 687","2 309 415 678"],"image":"assets/legacy-conditions/2006/manual-13.webp","imageWidth":200,"imageHeight":90},"14":{"question":"На стеклянной двери написано: «КЕНГУРУ ПРИГЛАШАЕТ ДРУЗЕЙ». Сколько из этих 23 букв выглядят одинаково с той и с другой стороны двери?","choices":["12","10","8","7","6"]},"15":{"question":"Вороны Дана, Нана, Лана и Зана сидят на заборе. Дана сидит посредине между Наной и Ланой. Расстояние между Наной и Даной такое же, как между Ланой и Заной. Между Даной и Заной расстояние 4 метра. Какое расстояние между Наной и Заной?","choices":["5 м","6 м","7 м","8 м","9 м"]},"16":{"question":"Ваня стреляет в тире. Он заплатил за 10 выстрелов. За каждое попадание в мишень Ваня получает право на два дополнительных выстрела. Ему удалось сделать 20 выстрелов. Сколько раз Ваня попал в мишень?","choices":["10","8","6","5","4"]},"17":{"question":"Сколько получится, если 2 десятка умножить на 5 десятков?","choices":["10","50","10 десятков","5 сотен","10 сотен"]},"18":{"question":"У Глаши есть набор фигурок, белых с одной стороны и цветных — с другой. Глаша сложила из своих фигурок прямоугольник так, как изображено на рисунке. Какая из фигурок (A) — (E) ей не понадобилась?","image":"assets/legacy-conditions/2006/manual-18.webp","imageWidth":538,"imageHeight":277},"19":{"question":"Если в некотором месяце 5 суббот, то в этом месяце не может быть","choices":["5 вторников","5 воскресений","5 четвергов","5 понедельников","5 пятниц"]},"20":{"question":"Электронные часы показывают часы и минуты (от 00:00 до 23:59). Сколько раз за сутки в наборе цифр на табло этих часов участвуют только цифры 2 и 5 (или одна из этих цифр)?","choices":["12","6","4","2","1"]},"21":{"question":"Антон и Миша считают деревья, растущие вокруг пруда. Они двигаются в одном направлении, но начинают счет с разных деревьев. То дерево, которое Миша назвал двадцатым, для Антона оказалось четвертым, а дерево, которое Миша назвал десятым, для Антона оказалось сорок шестым. Сколько деревьев растет вокруг пруда?","choices":["50","52","56","60","80"]},"22":{"question":"На каждой из 7 карточек на верхнем рисунке написано по две буквы. На нижнем рисунке – те же карточки, но в другом порядке. Какое «слово» могло получиться внизу?","choices":["НЕКУРУГ","УРУГКЕН","НРУГЕКУ","УГУРНЕК","НЕГРУКУ"],"image":"assets/legacy-conditions/2006/task-22.webp","imageWidth":359,"imageHeight":200},"23":{"question":"Если лягушонок зеленый, то он веселый. Если лягушонок не веселый, то он сидит на берегу. Все лягушата либо зеленые, либо пестренькие. Если лягушонок пестренький, то он плавает в воде. Тогда обязательно","choices":["все лягушата плавают в воде","все лягушата — не веселые","все лягушата — веселые","все лягушата — пестренькие","все веселые лягушата — зеленые"]},"24":{"question":"Кенгуру Попрыгун проснулся под пальмой и стал радостно скакать по дорожке, иногда меняя направление прыжков. Длина каждого его прыжка либо 2 метра, либо 4 метра, либо 7 метров. На каком расстоянии от пальмы он не мог оказаться после 10 прыжков?","image":"assets/legacy-conditions/2006/task-24.webp","imageWidth":698,"imageHeight":85},"25":{"question":"Сколько треугольников изображено на рисунке?","choices":["16","20","21","22","23"],"image":"assets/legacy-conditions/2006/task-25.svg","imageWidth":228,"imageHeight":199},"26":{"question":"В ребусе КЕН × Г = УРУ одинаковыми буквами зашифрованы одинаковые цифры, а разными — разные. Если К равно 2, то У равно","choices":["4","6","7","8","9"]}},"2007":{"1":{"question":"Сколько общих букв у слов КЕНГУРУ и МАТЕМАТИКА?","choices":["1","2","3","4","5"]},"2":{"question":"Какая фигурка содержит больше всего клеточек?","image":"assets/legacy-conditions/2007/task-02.webp","imageWidth":936,"imageHeight":181},"3":{"question":"На календаре 2007 год. Сумма цифр этого числа равна 9. Через сколько лет повторится такая же сумма цифр?","choices":["1 год","2 года","7 лет","9 лет","12 лет"]},"4":{"question":"Какие две маски одинаковые?","choices":["1 и 2","1 и 3","2 и 4","3 и 5","1 и 5"],"image":"assets/legacy-conditions/2007/task-04.webp","imageWidth":930,"imageHeight":181},"5":{"question":"Что не равно 5?","choices":["Лучшая оценка в школе.","Число носов у двух собак и трех котов.","Номер задачи, которую ты сейчас решаешь.","Число букв в слове ПЯТЬ.","Половина числа 10."]},"6":{"question":"Цифры 0, 3 и 7 написаны на трех карточках. Сколько различных трехзначных чисел можно составить из этих карточек?","choices":["2","3","4","5","6"],"image":"assets/legacy-conditions/2007/task-06.svg","imageWidth":220,"imageHeight":143},"7":{"question":"2 × 2 + 2 + 2 + 2 + 2 + 2 × 2 =?","choices":["12","16","20","24","32"]},"8":{"question":"Справа нарисована фигурка, состоящая из клеточек. Что нельзя вырезать из этой фигурки?","image":"assets/legacy-conditions/2007/task-08.webp","imageWidth":942,"imageHeight":265},"9":{"question":"Сколько нулей в записи числа миллион плюс тысяча плюс один?","choices":["2","3","4","5","6"]},"10":{"question":"Вес Васи – 21 кг. Когда он встал на весы, взяв на руки кота Тошу, весы показали 29 кг 500 г. С котенком Малышом на руках Вася весит 22 кг. Что покажут весы, если на них усадить Тошу и Малыша вместе?","choices":["1 кг","5 кг 500 г","7 кг 500 г","9 кг 500 г","51 кг 500 г"]},"11":{"question":"В каждую клетку квадрата 3 × 3 надо вписать одну из цифр 1, 2 или 3. Каждая цифра должна встречаться в каждой строчке и в каждом столбце. Три клетки уже заполнены. Какую цифру можно поставить вместо вопросительного знака?","choices":["только 1","только 2","только 3","2 или 3","1, 2 или 3"],"image":"assets/legacy-conditions/2007/task-11.svg","imageWidth":219,"imageHeight":220},"12":{"question":"Ваня старше Пети на 3 года и 1 день. Ваня родился 1 января 1997 года. Когда родился Петя?","choices":["2 января 2000 года","2 января 1994 года","31 декабря 1993 года","31 декабря 2000 года","31 декабря 1999 года"]},"13":{"question":"Вера разрезала квадратный листок бумаги со стороной 5 см на два прямоугольника. Периметр одного из этих прямоугольников равен 16 см. Чему равен периметр другого?","choices":["8 см","9 см","12 см","14 см","16 см"]},"14":{"question":"На ферме у Яна живут куры и свиньи, причем тех и других поровну. Сколько ног может быть у всех этих животных вместе?","choices":["16","22","26","48","52"]},"15":{"question":"Муравьишка ехал верхом на Гусенице 24 минуты, а потом пересел на Жука и проехал на нем в 4 раза больший путь. Сколько минут он ехал на Жуке, если Жук передвигается в 8 раз быстрее Гусеницы?","choices":["3 мин","6 мин","12 мин","48 мин","96 мин"]},"16":{"question":"Степа учится в школе. Если цифры в его возрасте поменять местами, то получится возраст его дедушки, которому больше 60 лет, но меньше 70. На сколько лет Степа моложе дедушки?","choices":["40","42","44","45","48"]},"17":{"question":"Две квадратные салфетки 9 см × 9 см лежат на столе так, что получается прямоугольник 9 см × 13 см. Какая площадь покрыта в два слоя?","choices":["36 см²","45 см²","54 см²","63 см²","72 см²"]},"18":{"question":"Роман, Федя, Лиза, Катя и Андрей пришли на занятие кружка. Роман пришел позже Лизы, Федя раньше Романа и сразу за Катей. Катя пришла раньше Лизы, но не была первой. Кто из ребят пришел на занятие третьим?","choices":["Роман","Андрей","Лиза","Катя","Федя"]},"19":{"question":"Квадратный лист бумаги сложили пополам, затем еще раз пополам и от полученного квадратика отрезали маленький уголок. Затем лист бумаги развернули. Что не могло получиться?","image":"assets/legacy-conditions/2007/task-19.webp","imageWidth":869,"imageHeight":269},"20":{"question":"В 1-а классе учится 36 ребят. Половина из них − мальчики. Ровно треть учеников этого класса еще не научилась выговаривать букву Р. Известно, что ровно 14 девочек уже говорят эту букву правильно. Сколько мальчиков выговаривают Р правильно?","choices":["6","8","10","12","18"]},"21":{"question":"Маша разделила восемь чисел 1, 2, 3, 4, 5, 6, 7, 8 на две четверки с равными суммами. При этом числа 1 и 3 оказались в одной четверке. Тогда в ней же оказалось и число","choices":["2","4","5","6","7"]},"22":{"question":"В любом месяце есть 4 субботы, но в некоторых месяцах суббот больше. Какое наибольшее число таких месяцев может быть в году?","choices":["1","2","3","4","5"]},"23":{"question":"Общее количество точек на противоположных гранях игрального кубика равно 7. Четыре одинаковых игральных кубика сложили вместе и закрасили некоторые грани. Сколько точек было на грани, отмеченной знаком ∗, если кубики приложены друг к другу по одинаковым граням?","choices":["5","3","2","1","нельзя определить"],"image":"assets/legacy-conditions/2007/task-23.webp","imageWidth":268,"imageHeight":185},"24":{"question":"Три сестры Анна, Ева и Лиза одинаково быстро и хорошо умеют навести порядок в квартире. Если любые две из этих девочек будут работать вместе, то справятся с уборкой за час. Сколько времени они потратят на уборку, если будут работать все трое вместе?","choices":["20 минут","30 минут","40 минут","45 минут","60 минут"]},"25":{"question":"В примере на умножение КЕН × ГА = 7 632 использованы все цифры от 1 до 9, каждая по одному разу. Какую цифру заменяет буква Г?","choices":["1","4","5","8","9"]},"26":{"question":"Электронные часы показывают часы и минуты, от 00:00 до 23:59. Сколько времени в течение суток на табло этих часов присутствует хотя бы одна цифра 2?","choices":["3 ч 45 мин","6 ч","6 ч 45 мин","10 ч 30 мин","12 ч"]}},"2008":{"1":{"question":"Сколько различных букв в словах УРА КЕНГУРУ?","choices":["7","6","5","4","3"]},"2":{"question":"На листе бумаги поставили точку и провели через нее четыре прямые. На сколько частей эти прямые разделили лист бумаги?","choices":["4","6","8","10","12"]},"3":{"question":"Через шесть с половиной часов наступит полночь. А сейчас который час?","choices":["21:30","6:30","20:30","17:30","10:30"]},"4":{"question":"Сколько веревочек на рисунке?","choices":["1","2","3","4","5"],"image":"assets/legacy-conditions/2008/task-04.webp","imageWidth":286,"imageHeight":275},"5":{"question":"Сколько месяцев имеют в названии ровно 4 буквы?","choices":["2","3","4","5","6"]},"6":{"question":"В первом аквариуме на 12 рыбок больше, чем во втором. Сколько рыбок надо переселить из первого аквариума во второй, чтобы рыбок в них стало поровну?","choices":["12","8","6","4","2"]},"7":{"question":"Дорожка выложена из 14 квадратных плит со стороной 1 м. Антон отметил центр каждой плиты и соединил эти точки линией. Какую длину имеет эта линия?","choices":["12 м","13 м","14 м","15 м","16 м"],"image":"assets/legacy-conditions/2008/task-07.webp","imageWidth":525,"imageHeight":157},"8":{"question":"Какое из этих чисел не равно остальным?","choices":["сто раз по двадцать","двадцать сотен","двести десятков","две тысячи","сто раз по двести"]},"9":{"question":"Никита кладет на лист бумаги два одинаковых треугольника (нарисованных справа) и обводит контур полученной фигуры. Какую фигуру он не сможет получить?","image":"assets/legacy-conditions/2008/task-09.webp","imageWidth":943,"imageHeight":316},"10":{"question":"Какую цифру или знак арифметического действия нужно поставить вместо *, чтобы равенство 1 + 1 * 1 − 2 = 100 стало верным?","choices":["+","−","×","0","1"]},"11":{"question":"Гоша выше Бориса, но ниже Антона. Витя выше Димы, но ниже Гоши. Кто из мальчиков самый высокий?","choices":["Антон","Борис","Витя","Гоша","Дима"]},"12":{"question":"Вася любит умножать на 3, Маша – прибавлять 2, а Петя – вычитать 1. В каком порядке детей надо вызвать к доске выполнить любимое действие, чтобы из 1 получить 4?","choices":["М, В, П","П, М, В","П, В, М","М, П, В","В, М, П"]},"13":{"question":"Фигура составлена из 6 спичек. Сережа переложил две спички. Какая из фигур (А) — (Г) не могла получиться?","image":"assets/legacy-conditions/2008/manual-13.webp","imageWidth":504,"imageHeight":370},"14":{"question":"У Даши 20 кубиков, у Маши 12 кубиков, у Глаши 8 кубиков, а у Наташи – 6 кубиков. Кто из девочек может построить куб из всех своих кубиков?","choices":["Даша","Маша","Глаша","Наташа","никто не может"]},"15":{"question":"В некоторой гостинице к приему гостей готово 5 трехместных номеров и один двухместный номер. Сколько еще двухместных номеров надо подготовить, чтобы разместить группу из 25 туристов?","choices":["3","4","5","6","8"]},"16":{"question":"Квадратный участок земли разбит на 4 части: газон Г, цветник Ц, огород О и сад С. Сад и цветник – квадраты. Периметр сада – 80 м, а цветника – 20 м. Чему равен периметр газона?","choices":["20 м","25 м","30 м","50 м","100 м"],"image":"assets/legacy-conditions/2008/task-16.svg","imageWidth":222,"imageHeight":222},"17":{"question":"В память о своем боевом прошлом старый пират отчеканил по одной монете достоинством 1000 дукатов, 3000 дукатов, 4000 дукатов, 6000 дукатов и 7000 дукатов. Сколькими способами он может набрать из них сумму в 14000 дукатов?","choices":["1","2","3","4","5"]},"18":{"question":"Сколько существует двузначных чисел, у которых цифра десятков меньше, чем цифра единиц?","choices":["50","45","36","18","9"]},"19":{"question":"Конкурс «Кенгуру», в котором ты сегодня участвуешь, проходит в России уже в 15-ый раз (всегда в марте). Первый раз Аня участвовала в 11-ом конкурсе, когда ей только что исполнилось 10 лет. В каком году она родилась?","choices":["1987","1989","1993","1994","1998"]},"20":{"question":"Три юных кенгуренка Кенг, Гур и Ру сидят на весах. Если с весов спрыгнет Кенг, то весы покажут 3 кг. Если спрыгнет Гур, то весы покажут 4 кг, а если спрыгнет Ру, то весы покажут 5 кг. Сколько весят все кенгурята вместе?","choices":["12 кг","10 кг","8 кг","7 кг","6 кг"]},"21":{"question":"У Тани и ее родителей общий день рождения – 1 января. В январе 2007 года Таня была в 6 раз младше своей мамы, а в январе 2008 – в 6 раз младше папы. На сколько лет папа старше мамы?","choices":["1","4","5","6","7"]},"22":{"question":"Точки А, B, C и D отмечены на прямой в некотором порядке. Известны расстояния: от А до B – 13 см, от B до C – 11 см, от C до D – 14 см и от D до А – 12 см. Чему равно расстояние между наиболее удаленными точками?","choices":["14 см","25 см","27 см","38 см","50 см"]},"23":{"question":"Один странный мальчик по четвергам и пятницам говорит только правду, по вторникам всегда лжет, а в остальные дни недели он может и солгать, и сказать правду. Семь дней подряд мальчика спрашивали, как его зовут. Первые шесть ответов, по порядку, были таковы: Женя, Боря, Вася, Боря, Петя, Боря. Как он ответил на седьмой день?","choices":["Женя","Боря","Петя","Вася","невозможно определить"]},"24":{"question":"Фонтан на площади старинного города связан с часами на башне: он работает, когда хотя бы одна из стрелок часов находится между цифрами 3 и 4 или между цифрами 8 и 9. Сколько времени в течение суток этот фонтан работает?","choices":["11 ч 40 мин","9 ч 30 мин","7 ч 20 мин","5 ч 40 мин","4 ч"],"image":"assets/legacy-conditions/2008/task-24.svg","imageWidth":232,"imageHeight":233},"25":{"question":"Из каждой заготовки (А) — (Д) можно склеить кубик. 4 кубика получатся одинаковыми, а один будет от них отличаться. Из какой заготовки получится этот кубик?","image":"assets/legacy-conditions/2008/manual-25.webp","imageWidth":674,"imageHeight":148},"26":{"question":"В первый понедельник каждого из трех летних месяцев Маша записывала число, на которое пришелся этот понедельник, а в конце лета сложила три записанных числа. Какая наименьшая сумма могла получиться?","choices":["3","8","9","10","12"]}},"2009":{"1":{"question":"Сколько треугольников на рисунке?","choices":["2","3","4","5","6"],"image":"assets/legacy-conditions/2009/task-01.webp","imageWidth":293,"imageHeight":292},"2":{"question":"200 × 9 + 200 + 9 =?","choices":["418","1909","2009","4018","20009"]},"3":{"question":"Сколько всего вершин у четырех кубиков?","choices":["32","24","16","12","4"]},"4":{"question":"Где кенгуру?","choices":["В круге и в треугольнике, но не в квадрате.","В круге и в квадрате, но не в треугольнике.","В треугольнике и в квадрате, но не в круге.","Не в треугольнике и не в квадрате, но в круге.","Не в круге и не в треугольнике, но в квадрате."],"image":"assets/legacy-conditions/2009/manual-04.webp","imageWidth":200,"imageHeight":197},"5":{"question":"В пятиэтажном доме в каждом подъезде на каждом этаже расположено по 4 квартиры. На каком этаже находится квартира с номером 71?","choices":["1","2","3","4","5"]},"6":{"question":"На клетчатой бумаге нарисовано число 930 (см. рисунок). Сколько маленьких квадратиков должно поменять цвет, чтобы получилось число 806?","choices":["5","6","7","8","9"],"image":"assets/legacy-conditions/2009/task-06.svg","imageWidth":232,"imageHeight":231},"7":{"question":"Вася подсчитал число дней в двух идущих подряд месяцах. Какое число он не мог получить?","choices":["62","60","58","59","61"]},"8":{"question":"Шоколадная плитка состоит из одинаковых долек. Маленький Владик разделил ее «по-честному»: сначала он отломал полоску из 5 долек для бабушки, а затем полоску из 7 долек для дедушки (см. рисунок). Сколько долек у него осталось?","choices":["23","28","30","35","40"],"image":"assets/legacy-conditions/2009/task-08.webp","imageWidth":198,"imageHeight":131},"9":{"question":"Произведение цифр двузначного числа не может равняться","choices":["40","36","20","13","12"]},"10":{"question":"В 3 часа ночи в замке появилось Привидение. Часы на башне замка, которые до этого показывали правильное время, пошли с обычной скоростью, но в другую сторону. Привидение исчезло с рассветом, в 4 часа 45 минут. Какое время в этот момент показывали часы?","choices":["полночь","1 ч 15 мин","1 ч 30 мин","2 ч 15 мин","7 ч 45 мин"]},"11":{"question":"В танцевальной студии занимались 25 мальчиков и 19 девочек. Каждую неделю в группу приходят два новых мальчика и три новых девочки. Через сколько недель мальчиков и девочек в этой студии станет поровну?","choices":["6","5","4","3","2"]},"12":{"question":"У скольких трехзначных чисел сумма цифр равна 2?","choices":["0","1","2","3","4"]},"13":{"question":"На картинке справа изменили цвет каждой клеточки: белый – на красный, и наоборот. Что получилось?","image":"assets/legacy-conditions/2009/task-13.webp","imageWidth":976,"imageHeight":247},"14":{"question":"В комнате сидят несколько кошек и собак. Кошачьих лап в комнате вдвое больше, чем собачьих носов. Тогда кошек в комнате","choices":["вдвое больше, чем собак","столько же, сколько собак","вдвое меньше, чем собак","в 4 раза меньше, чем собак","в 4 раза больше, чем собак"]},"15":{"question":"Город разделен улицами на квадратные кварталы. Машина выезжает из точки М и на каждом перекрестке поворачивает налево или направо. Проехав один квартал, машина повернула направо, потом три раза налево, а потом еще два раза направо. На каком из рисунков изображен маршрут машины?","image":"assets/legacy-conditions/2009/task-15.webp","imageWidth":976,"imageHeight":157},"16":{"question":"Белки Алли, Элли и Салли нашли вместе семь орехов. Каждая из них нашла хотя бы по одному ореху, и у всех оказалось разное число орехов. Алли нашла орехов меньше всех, а Элли – больше всех. Сколько орехов нашла Элли?","choices":["4","3","2","1","невозможно определить"]},"17":{"question":"Аня и Петя живут на набережной. Слева от дома Ани на набережной находится 47 домов, а справа — 23 дома. От дома Пети слева и справа по набережной находится одинаковое число домов. Сколько домов расположено между домами Ани и Пети?","choices":["10","11","12","13","14"]},"18":{"question":"Из палочек можно выкладывать цифры как на рисунке. Какова сумма цифр самого большого числа, которое удастся выложить, использовав ровно 15 палочек?","choices":["5","15","27","35","45"],"image":"assets/legacy-conditions/2009/task-18.webp","imageWidth":325,"imageHeight":189},"19":{"question":"Букет состоит из 4 цветков: красного, голубого, желтого и белого. Пчела Майя садится на каждый цветок в букете только один раз. Она начинает с красного цветка и не перелетает с желтого сразу на белый. Сколькими способами Майя может облететь все цветы?","choices":["6","4","3","2","1"]},"20":{"question":"Будем называть шестизначное число счастливым, если у него сумма цифр, стоящих на нечетных местах, равна сумме цифр, стоящих на четных местах. В каком случае можно заполнить пустые места цифрами так, чтобы получилось счастливое число?","image":"assets/legacy-conditions/2009/task-20.webp","imageWidth":913,"imageHeight":98},"21":{"question":"Какую фигуру нельзя составить из двух костяшек домино, изображенных справа?","image":"assets/legacy-conditions/2009/task-21.webp","imageWidth":951,"imageHeight":267},"22":{"question":"Дикарь Пятница написал в строчку несколько различных чисел, не превосходящих 10. Робинзон Крузо заметил, что в любой паре соседних чисел одно из них делится на другое без остатка. Какое наибольшее количество чисел мог выписать Пятница?","choices":["6","7","8","9","10"]},"23":{"question":"В доме между любыми двумя комнатами не более одной двери, и из каждой комнаты не более одной двери ведет в сад. Всего в доме 12 дверей. Какое наименьшее число комнат может быть в этом доме?","choices":["3","4","5","6","7"]},"24":{"question":"В таблицу 3×3 вписывают цифры так, что все 6 сумм, полученных при сложении цифр из каждой строки и каждого столбца, оказываются разными. Чему равна самая маленькая сумма всех цифр в таблице с таким свойством?","choices":["7","8","9","10","12"]},"25":{"question":"В равенстве K + A + N + G + A + R + O + O = 56 разные буквы обозначают разные цифры, а одинаковые буквы — одинаковые цифры. Наименьшее возможное значение суммы K + A + N равно","choices":["3","9","13","17","19"]},"26":{"question":"На рисунке изображены три одинаковых кубика. На гранях кубиков нарисованы цифры: 0, 1, 3, 4, 5, 9. Чему равна сумма чисел на нижних гранях этих кубиков?","choices":["10","9","8","7","6"],"image":"assets/legacy-conditions/2009/task-26.webp","imageWidth":409,"imageHeight":125}},"2010":{"1":{"question":"Что можно получить из слова КЕНГУРУ, если стереть некоторые буквы?","image":"assets/legacy-conditions/2010/manual-01.webp","imageWidth":771,"imageHeight":77},"2":{"question":"Дети измерили шагами длину дорожки. У Ани получилось 17 шагов, у Наташи 15, у Дениса 14, у Вани 13 и у Тани 12. Кто из этих детей имеет самый длинный шаг?","choices":["Аня(А","Наташа(Б","Денис(В","Ваня(Г","Таня(Д"]},"3":{"question":"Какая цифра зашифрована значком ●, если ● + 12 = ● + ● + ● + ●?","choices":["2","3","4","5","6"]},"4":{"question":"Лабиринт устроен так, что кот может добраться до молока, а мышка — до сыра, но они не могут встретиться. Какая часть лабиринта закрыта квадратиком?","image":"assets/legacy-conditions/2010/task-04.webp","imageWidth":982,"imageHeight":391},"5":{"question":"У стоножки Евы 100 ножек. Вчера она купила и надела 16 пар новых башмаков. Несмотря на это, 14 ножек остались босыми. Сколько ножек были обуты до того, как она купила башмаки?","choices":["27","40","54","70","77"]},"6":{"question":"На рисунке показано, как цифра 4 отражается в двух зеркалах. Что будет видно на месте знака вопроса, если вместо цифры 4 взять цифру 6?","image":"assets/legacy-conditions/2010/manual-06.webp","imageWidth":570,"imageHeight":157},"7":{"question":"Урок начался в 11:45 и длился 40 минут. Ровно в середине урока Вася чихнул. В какой момент это произошло?","choices":["12:00","12:05","12:10","12:15","12:20"]},"8":{"question":"За весь ноябрь 2009 года в Санкт-Петербурге солнце светило всего 13 часов. Сколько часов в течение этого месяца в городе не было солнца?","choices":["287","347","683","707","731"]},"9":{"question":"Сёма выписал все трехзначные числа, у которых средняя цифра равна 5, а сумма первой и последней равна 7. Сколько чисел он выписал?","choices":["2","4","7","8","10"]},"10":{"question":"В магазине продаются модели машинок трех видов: по 15 руб., 21 руб. и 28 руб., а набор из трех таких машинок стоит 56 рублей. Мама обещала Пете купить все три модели. Сколько рублей можно сэкономить, если купить набор, а не все три машинки по отдельности?","choices":["2","3","4","7","8"]},"11":{"question":"У мухи 6 лапок, у паука — 8. Две мухи и три паука вместе имеют столько же лапок, сколько 10 попугаев и","choices":["2 кошки","3 белки","4 собаки","5 зайцев","6 лисиц"]},"12":{"question":"Ира, Катя, Аня, Оля и Лена учатся в одной школе. Две девочки учатся в 3 «а» классе, три — в 3 «б». Оля учится не вместе с Катей и не вместе с Леной, Аня учится не вместе с Ирой и не вместе с Катей. Кто из девочек учится в 3 «а» классе?","choices":["Аня и Оля","Ира и Лена","Ира и Оля","Ира и Катя","Катя и Лена"]},"13":{"question":"Конструкция на рисунке весит 128 граммов и находится в равновесии (вес горизонтальных планок и вертикальных нитей не учитывается). Сколько весит звездочка?","choices":["6 г","7 г","8 г","16 г","20 г"],"image":"assets/legacy-conditions/2010/task-13.webp","imageWidth":321,"imageHeight":192},"14":{"question":"Карл и Клара живут в многоэтажном доме. Клара живет на 12 этажей выше, чем Карл. Однажды Карл пошел в гости к Кларе. Пройдя половину пути, он оказался на 8 этаже. На каком этаже живет Клара?","choices":["12","14","16","20","24"]},"15":{"question":"Произведение 60 × 60 × 24 × 7 равняется","choices":["числу минут в семи неделях","числу часов в шестидесяти днях","числу секунд в семи часах","числу секунд в одной неделе","числу минут в двадцати четырех неделях"]},"16":{"question":"На рисунке справа изображена керамическая плитка. Какую картинку нельзя составить из четырех таких плиток?","image":"assets/legacy-conditions/2010/task-16.webp","imageWidth":954,"imageHeight":222},"17":{"question":"Два года назад котам Тоше и Малышу вместе было 15 лет. Сейчас Тоше 13 лет. Через сколько лет Малышу будет 9 лет?","choices":["1","2","3","4","5"]},"18":{"question":"Что в миллион раз легче тонны?","choices":["1 ц","1 кг","100 г","1 г","1 мг"]},"19":{"question":"В ребусе AAA − BB + C = 260 одинаковыми буквами зашифрованы одинаковые цифры, а разными — разные. Тогда сумма A + B + C равна","choices":["20","14","12","10","7"]},"20":{"question":"Вместо звездочек Вася вписал такие числа, что суммы чисел в обеих строчках стали одинаковы. Чему равна разность вписанных чисел?","choices":["10","20","30","40","они равны"],"image":"assets/legacy-conditions/2010/task-20.webp","imageWidth":584,"imageHeight":111},"21":{"question":"Из листа клетчатой бумаги Маша вырезала кусок, состоящий из целых клеточек. Она резала по сторонам клеточек, причем четыре отрезка, отмеченных на рисунке, оказались на границе вырезанного куска. Из какого наименьшего количества клеточек мог состоять этот кусок?","choices":["13","11","9","8","7"],"image":"assets/legacy-conditions/2010/task-21.svg","imageWidth":220,"imageHeight":220},"22":{"question":"Катя выписала все числа от 1 до 1000 «змейкой» в таблицу с пятью столбцами (см. рисунок). Ее брат стер некоторые числа. Как могут выглядеть две соседние строки из получившейся таблицы?","image":"assets/legacy-conditions/2010/manual-22.webp","imageWidth":778,"imageHeight":360},"23":{"question":"Мама разрешает Пете играть в компьютерные игры только по понедельникам, пятницам и нечетным числам. Какое наибольшее число дней подряд Петя сможет играть?","choices":["7","6","4","3","2"]},"24":{"question":"Сколько треугольников изображено на рисунке?","choices":["26","42","50","52","54"],"image":"assets/legacy-conditions/2010/task-24.svg","imageWidth":199,"imageHeight":220},"25":{"question":"Учитель сказал, что в школьной библиотеке примерно 2000 книг, и предложил ребятам угадать точное количество книг. Аня назвала число 1995, Боря — 1998, Вика — 2009, Гена — 2010, а Дима — 2015. Тогда учитель сказал, что точно не угадал никто, а ошибки были такими: 12, 8, 7, 6 и 5 (возможно, в другом порядке). Кто из ребят оказался ближе всего к правильному ответу?","choices":["Аня","Боря","Вика","Гена","Дима"]},"26":{"question":"Знайка, Незнайка, Винтик и Шпунтик съели торт. Они ели по очереди, и каждый из них ел столько времени, сколько понадобилось бы трем другим едокам, чтобы, «работая» вместе, съесть половину торта. Во сколько раз быстрее они съели бы торт, если бы ели его не по очереди, а все вместе?","choices":["2","3","4","5","6"]}},"2011":{"1":{"question":"Вася хочет написать слово КЕНГУРУ. Он начал писать в среду и пишет по одной букве в день. В какой день недели Вася напишет последнюю букву?","choices":["понедельник","вторник","среда","четверг","пятница"]},"2":{"question":"Первобытному человеку нужно уравновесить два набора камней. Какой камень он должен добавить справа?","image":"assets/legacy-conditions/2011/manual-02.webp","imageWidth":953,"imageHeight":253},"4":{"question":"2 × 0 × 11 + 20 × 11 − 201 × 1 = ?","choices":["0","19","31","421","443"]},"5":{"question":"У Димы в кармане 7 монет, каждая либо 5 рублей, либо 10 рублей. Сколько всего денег может быть у него в кармане?","choices":["30 руб.","37 руб.","45 руб.","57 руб.","75 руб."]},"6":{"question":"Какая буква не будет накрыта закрашенным квадратиком, если этот прямоугольник согнуть по жирной линии?","choices":["А","Б","В","Г","Д"],"image":"assets/legacy-conditions/2011/manual-06.webp","imageWidth":202,"imageHeight":184},"7":{"question":"Сторона клетки на рисунке равна 1. Какова длина самого короткого маршрута, который идет из A в B по сторонам клеток, обходя кляксы?","choices":["8","10","12","14","16"],"image":"assets/legacy-conditions/2011/manual-07.webp","imageWidth":176,"imageHeight":170},"8":{"question":"На день рождения Васи мама испекла два торта. Каждый из них она разделила на четыре части. Потом каждую из получившихся частей разделила еще на три кусочка. Каждый из гостей получил по кусочку, один кусочек съел Вася, и еще осталось два кусочка. Сколько гостей было на дне рождения у Васи?","choices":["27","24","22","21","13"]},"9":{"question":"Про одну из пяти карточек, нарисованных справа, Маша сказала: «Она не квадратная и не белая, она круглая или треугольная». Какая это карточка?","choices":["А","Б","В","Г","Д"],"image":"assets/legacy-conditions/2011/manual-09.webp","imageWidth":213,"imageHeight":113},"10":{"question":"Электронные часы показывают часы и минуты. Сколько всего раз с 7 часов до 23 часов они покажут четыре одинаковые цифры?","choices":["1","2","3","5","12"]},"11":{"question":"Какая фигурка имеет самую большую площадь?","image":"assets/legacy-conditions/2011/manual-11.webp","imageWidth":977,"imageHeight":144},"12":{"question":"В кувшине в пять раз больше воды, чем в чайнике, а в чайнике на 8 стаканов воды меньше, чем в кувшине. Сколько стаканов воды в кувшине и чайнике вместе?","choices":["12","14","16","18","20"]},"13":{"question":"В каждом квадратике волшебного лабиринта лежит по кусочку сыра. Мышка хочет пройти по лабиринту от входа к выходу, поедая сыр по дороге. Она не может посещать один квадратик дважды. Какое наибольшее число кусочков сыра она сможет съесть?","choices":["17","33","37","41","49"],"image":"assets/legacy-conditions/2011/manual-13.webp","imageWidth":266,"imageHeight":293},"14":{"question":"Каждый участник викторины вначале получает 10 баллов и должен ответить на 10 вопросов. За каждый правильный ответ ему добавляют 1 балл, а за неправильный ответ у него вычитают 1 балл. Миша получил в результате 14 баллов. Сколько неверных ответов он дал?","choices":["7","6","5","4","3"]},"15":{"question":"Андрей хочет разрезать фигуру, изображенную справа, на несколько одинаковых частей. Фигурки какого вида у него не могут получиться?","image":"assets/legacy-conditions/2011/manual-15.webp","imageWidth":788,"imageHeight":369},"16":{"question":"Из трех карточек, изображенных справа, можно составлять числа, например, 989 и 986. Сколько всего различных трехзначных чисел можно составить из этих карточек?","choices":["12","9","8","6","4"],"image":"assets/legacy-conditions/2011/manual-16.webp","imageWidth":216,"imageHeight":172},"17":{"question":"Аня, Боря, Вика, Гриша, Дима и Егор по одному разу бросили игральный кубик. Все они получили различные результаты (от 1 до 6 очков). У Ани очков вдвое больше, чем у Бори и втрое больше, чем у Вики. У Гриши очков в четыре раза больше, чем у Димы. Сколько очков у Егора?","choices":["2","3","4","5","6"]},"18":{"question":"Из 36 одинаковых кубиков Нина построила изгородь вокруг квадратного участка (часть этой изгороди изображена на рисунке). Сколько еще таких кубиков понадобится ей, чтобы заполнить огороженный участок?","choices":["36","49","64","81","100"],"image":"assets/legacy-conditions/2011/manual-18.webp","imageWidth":253,"imageHeight":136},"19":{"question":"В комнате 12 щенков, каждый из них шумный или кусачий. Кусачих щенков 8, а шумных — 9. Сколько среди них шумных и кусачих одновременно?","choices":["3","4","5","6","8"]},"20":{"question":"Никита терпеливо выписал все трехзначные числа, цифры которых идут в убывающем порядке. Чему равна разность между самым большим и самым маленьким из этих чисел?","choices":["665","777","800","899","966"]},"21":{"question":"Саша вписал числа 1, 2, 3, 4, 5, 6, 7 и 8 в кружочки. Оказалось, что сумма чисел, стоящих на каждой стороне квадрата, равна 13. Чему равна сумма чисел в закрашенных кружочках?","choices":["12","13","14","16","20"],"image":"assets/legacy-conditions/2011/manual-21.webp","imageWidth":181,"imageHeight":177},"22":{"question":"В некотором месяце было 5 суббот и 5 воскресений, но всего 4 пятницы и 4 понедельника. Тогда в следующем месяце будет","choices":["5 воскресений","5 пятниц","5 вторников","5 суббот","5 четвергов"]},"23":{"question":"Три одинаковых игральных кубика (сумма очков на противоположных гранях равна 7) склеили одинаковыми гранями, получив «столбик». Что можно увидеть на передней грани этого столбика?","image":"assets/legacy-conditions/2011/manual-23.webp","imageWidth":942,"imageHeight":185},"24":{"question":"Коты Тоша и Малыш обедают вместе с котенком Яшей. Тоша ест вдвое быстрее Малыша, а Малыш — вдвое быстрее Яши. Яше дали 6 маленьких рыбок, а Тоше и Малышу — по 12 таких же рыбок. Тоша съел свою порцию за 3 минуты и затем помог Малышу закончить обед. После этого они стали ждать, когда же со своей порцией справится Яша. Сколько времени они ждали?","choices":["1 мин","2 мин","3 мин","4 мин","5 мин"]},"25":{"question":"В числовом ребусе KANG − AROO = 2011 буквами K, A, N, G, R и O обозначены разные цифры. Сколько различных значений может принимать буква K?","choices":["1","2","3","4","5"]},"26":{"question":"Стерев в числе 20311 цифру 3, получим число 2011. Сколько всего существует пятизначных чисел, из которых можно получить число 2011, удалив одну цифру?","choices":["45","46","48","49","50"]}},"2012":{"1":{"question":"Саша рисует на плакате слова УРА КЕНГУРУ. Одинаковые буквы он рисует одним цветом, а разные буквы — разными цветами. Сколько различных цветов ему понадобится?","choices":["6","7","8","9","10"]},"2":{"question":"Один будильник спешит на 25 минут и показывает 7 часов 50 минут. Какое время показывает другой будильник, который отстает на 15 минут?","choices":["7 час 10 мин","7 час 25 мин","7 час 35 мин","7 час 40 мин","8 час"]},"3":{"question":"Только на одной из этих пяти картинок площадь закрашенной части не равна площади белой части. На какой?","image":"assets/legacy-conditions/2012/task-03.webp","imageWidth":928,"imageHeight":116},"4":{"question":"Три воздушных шарика стоят на 12 рублей больше, чем один шарик. Сколько стоит один шарик?","choices":["4 руб.","6 руб.","8 руб.","10 руб.","12 руб."]},"5":{"question":"На каком из рисунков клеточки A2, B1 и C3 закрашены?","image":"assets/legacy-conditions/2012/task-05.webp","imageWidth":950,"imageHeight":138},"6":{"question":"В школе для зверей учатся 3 котенка, 4 утенка, 2 гусенка и несколько щенков. Когда учитель пересчитал лапы всех своих учеников, получилось 44. Сколько щенков учится в школе?","choices":["6","5","4","3","2"]},"7":{"question":"Что не равно семи?","choices":["число дней в неделе","число букв в слове КЕНГУРУ","полдюжины","номер этой задачи","число цветов радуги"]},"8":{"question":"Плитки двух видов были выложены на стене в шахматном порядке. Несколько плиток упали со стены (см. рисунок). Сколько полосатых плиток упало?","choices":["9","8","7","6","5"],"image":"assets/legacy-conditions/2012/task-08.webp","imageWidth":312,"imageHeight":201},"9":{"question":"Петя задумал число, прибавил к нему 3, сумму умножил на 50, снова прибавил 3, умножил результат на 4 и получил 2012. Какое число задумал Петя?","choices":["11","9","8","7","5"]},"10":{"question":"В феврале 2012 года в зоопарке родился маленький кенгуру. Сегодня, 15 марта, ему исполняется 20 дней. В какой день он родился?","choices":["19 февраля","21 февраля","23 февраля","24 февраля","26 февраля"]},"11":{"question":"На лист бумаги Вася наклеил один за другим 5 одинаковых квадратов. Видимые части этих квадратов на рисунке помечены буквами. В каком порядке Вася наклеивал квадраты?","choices":["А, Б, В, Г, Д","Б, Г, В, Д, А","А, Д, В, Б, Г","Г, Д, Б, В, А","Г, Б, В, Д, А"],"image":"assets/legacy-conditions/2012/task-11.webp","imageWidth":207,"imageHeight":176},"12":{"question":"Блоха прыгает по длинной лестнице. Она может прыгать или на 3 ступеньки вверх, или на 4 ступеньки вниз. За какое наименьшее число прыжков она может перебраться с земли на 22-ю ступеньку?","choices":["7","9","10","12","15"]},"13":{"question":"Федя выложил правильную цепочку из семи доминошек (число точек в соседних квадратиках двух разных доминошек всегда одинаково). На всех доминошках вместе было 33 точки. Потом Федя забрал две доминошки из полученной цепочки (см. рисунок). Сколько точек было в квадратике, в котором стоит знак вопроса?","choices":["2","3","4","5","6"],"image":"assets/legacy-conditions/2012/task-13.webp","imageWidth":452,"imageHeight":236},"14":{"question":"За год до рождения Кати ее родителям вместе было 40 лет. Сколько сейчас лет Кате, если через 2 года ей и ее родителям вместе будет 90 лет?","choices":["15","14","13","8","7"]},"15":{"question":"Четвероклассница Маша и ее брат первоклассник Миша решали задачи конкурса «Кенгуру» для 3–4 классов. В результате оказалось, что Миша получил не 0 баллов, а Маша — не 100 баллов. На какое наибольшее число баллов Маша могла обогнать Мишу?","choices":["92","94","95","96","97"]},"16":{"question":"У правильно идущих «странных» часов перепутаны стрелки (часовая, минутная и секундная). В 12: 55: 30 стрелки располагались так, как показано на рисунке справа. Что покажут эти часы в 20 часов 12 минут?","image":"assets/legacy-conditions/2012/task-16.webp","imageWidth":958,"imageHeight":424},"17":{"question":"На рыбалку отправились пятеро мужчин из одной семьи: дедушка, 2 его сына и 2 внука. Их зовут: Борис Григорьевич, Григорий Викторович, Андрей Дмитриевич, Виктор Борисович, и Дмитрий Григорьевич. Как в детстве звали дедушку?","choices":["Андрюша","Боря","Витя","Гриша","Дима"]},"18":{"question":"Параллелепипед состоит из четырех частей. Каждая часть состоит из 4 кубиков одинакового цвета (см. рисунок). Какую форму имеет белая часть?","image":"assets/legacy-conditions/2012/task-18.webp","imageWidth":963,"imageHeight":264},"19":{"question":"В футболе команда получает за победу 3 очка, за ничью — 1 очко, а за поражение — 0 очков. Команда сыграла 38 матчей и получила 80 очков. Какое наибольшее число раз эта команда могла проиграть?","choices":["12","11","10","9","8"]},"20":{"question":"К пятизначному числу, сумма цифр которого равна 2, прибавили двузначное число. Получилось снова пятизначное число, сумма цифр которого равна 2. Какое число получилось?","choices":["20000","11000","10100","10010","10001"]},"21":{"question":"Недалеко от Венеции расположены три острова: Мурано, Бурано и Торчелло. Посетить Торчелло можно только побывав по дороге и на Мурано, и на Бурано. Каждый из 15 туристов посетил хотя бы один остров. При этом 5 человек посетили Торчелло, 13 человек побывали на Мурано и 9 человек — на Бурано. Сколько туристов посетили ровно два острова?","choices":["2","3","4","5","9"]},"22":{"question":"Бумажный кубик разрезали и развернули. Какие из фигур 1–5 могли получиться?","choices":["все","только 1, 2, 4","только 1, 2, 4, 5","только 1, 4, 5","только 1, 2, 3"],"image":"assets/legacy-conditions/2012/task-22.webp","imageWidth":937,"imageHeight":121},"23":{"question":"Никита выбрал два трехзначных числа, у которых совпадают суммы цифр. От большего числа он отнял меньшее. Какое самое большое число мог получить Никита?","choices":["792","801","810","890","900"]},"24":{"question":"В полдень из столицы в город А вышли скороход и торговец. Одновременно по той же дороге навстречу им из А вышел отряд стражников. Через час стражники встретили скорохода, еще через 2 часа они встретили торговца, а еще через 3 часа стражники прибыли в столицу. Во сколько раз быстрее торговца идет скороход?","choices":["2","3","4","5","6"]},"25":{"question":"Сколько всего квадратиков, образованных выделенными линиями, изображено на рисунке?","choices":["43","58","62","63","66"],"image":"assets/legacy-conditions/2012/manual-25.webp","imageWidth":183,"imageHeight":177},"26":{"question":"В равенстве КЕН = ГУ × РУ разными буквами обозначены разные ненулевые цифры, а одинаковыми буквами — одинаковые цифры. Найдите Е, если известно, что число КЕН — самое маленькое из возможных.","choices":["2","5","6","8","9"]}},"2013":{"1":{"question":"Какую из букв слова КЕНГА можно написать, не отрывая карандаша от бумаги и не проходя по одной линии дважды?","choices":["К","Е","Н","Г","А"]},"2":{"question":"В равенстве 4●+ 5●= 104 символом ● заменена одна и та же цифра. Какая?","choices":["2","4","5","6","7"]},"3":{"question":"Какая геометрическая фигура отсутствует на этом рисунке?","choices":["круг","треугольник","квадрат","прямоугольник","шестиугольник"],"image":"assets/legacy-conditions/2013/task-03.webp","imageWidth":159,"imageHeight":224},"4":{"question":"Миша измерил длины пяти палочек и записал результаты этих измерений. Какой из результатов А–Д самый большой?","choices":["3 дм 2 см","3 см 7 мм","35 мм","3 см","302 мм"]},"5":{"question":"Пятеро мальчиков обсуждали свойства числа 325. Андрей: «Это трехзначное число». Боря: «Все цифры этого числа различны». Витя: «Сумма его цифр равна 10». Гриша: «Цифра единиц равна 5». Даня: «Все его цифры нечетны». Кто из мальчиков ошибся?","choices":["Андрей","Боря","Витя","Гриша","Даня"]},"6":{"question":"У Пети было 36 конфет. Он раздал все конфеты гостям поровну. Сколько гостей у него могло быть?","choices":["5","6","7","8","10"]},"7":{"question":"Прямоугольное зеркало разбилось. Какой кусочек выпал?","image":"assets/legacy-conditions/2013/task-07.webp","imageWidth":976,"imageHeight":259},"8":{"question":"Когда Буратино врет, его нос удлиняется на 6 см. Когда он говорит правду, его нос становится короче на 2 см. Утром длина его носа была 9 см. За день он три раза соврал и два раза сказал правду. Какой длины стал нос у Буратино к вечеру?","choices":["14 см","15 см","19 см","23 см","31 см"]},"9":{"question":"Аня зашла в парк и пошла по аллее в направлении, указанном стрелочкой. На каждом перекрестке она поворачивала направо или налево. Сначала Аня повернула направо, затем налево, потом опять налево, затем направо, потом еще раз направо и дошла до следующего перекрестка. В каком месте оказалась Аня?","choices":["A","Б","В","Г","Д"],"image":"assets/legacy-conditions/2013/task-09.webp","imageWidth":437,"imageHeight":462},"10":{"question":"В этом году конкурс «Кенгуру» проводится в России в двадцатый раз. Федин папа участвовал в самом первом конкурсе, когда учился в десятом классе. Сколько лет ему может быть сейчас?","choices":["20","27","37","50","55"]},"11":{"question":"Сколько чисел между 20 и 30 делятся на свою последнюю цифру?","choices":["2","3","4","5","6"]},"12":{"question":"22 марта Наташа сказала: «Позавчера оставалась неделя до моего дня рождения». Когда она будет вспоминать, что неделю назад был ее день рождения?","choices":["27 марта","29 марта","2 апреля","3 апреля","5 апреля"]},"13":{"question":"Саша хочет закрасить несколько квадратиков на рисунке так, чтобы среди них никакие два не имели общей стороны. Какое наибольшее число квадратиков сможет закрасить Саша?","choices":["8","7","6","5","4"],"image":"assets/legacy-conditions/2013/task-13.webp","imageWidth":200,"imageHeight":111},"14":{"question":"В марте кот Тоша проспал ровно 2 недели. Сколько часов он бодрствовал в этом месяце?","choices":["(31− 7) ⋅ 2 ⋅ 24","(31 − 7 ⋅ 2) ⋅ 24 ⋅ 60","(30 − 7 ⋅ 2) ⋅ 24","(30 − 7 ⋅ 2) ⋅ 24 ⋅ 60","(31− 7 ⋅ 2) ⋅ 24"]},"15":{"question":"Одноклассники Тони, Бетти, Кэтти и Энди родились в один год. Их дни рождения: 20 февраля, 12 апреля, 12 мая и 25 мая. Дни рождения Бетти и Энди в одном месяце, а дни рождения Энди и Кэтти приходятся на одно число. Кто из детей самый старший?","choices":["Тони","Бетти","Кэтти","Энди","невозможно определить"]},"16":{"question":"В квадратной коробке в два слоя уложены одинаковые квадратные шоколадки. Кирилл съел все 20 шоколадок, которые лежали в верхнем слое вдоль стенок коробки. Сколько шоколадок было в этой коробке сначала?","choices":["50","52","70","72","98"]},"17":{"question":"Отцу сейчас 33 года, а его трем сыновьям 5, 6 и 10 лет. Через сколько лет трем сыновьям вместе будет столько же лет, сколько будет отцу?","choices":["4","6","8","10","12"]},"18":{"question":"У Кати есть 6 деталей, изображенных на рисунке. Из пяти деталей она сложила 2 фигуры: прямоугольник, одна из сторон которого равна 6, и квадрат. Какая деталь оказалась лишней?","image":"assets/legacy-conditions/2013/task-18.webp","imageWidth":965,"imageHeight":300},"19":{"question":"Мама купила трем своим детям 17 маленьких пирожных. Миша съел в два раза больше пирожных, чем Маша, а Даша съела больше Маши, но меньше Миши. Сколько пирожных съела Даша?","choices":["4","5","6","7","8"]},"20":{"question":"Сколько треугольников на рисунке?","choices":["8","9","14","15","16"],"image":"assets/legacy-conditions/2013/task-20.webp","imageWidth":178,"imageHeight":151},"21":{"question":"Из детей, которые пришли в гости к Наде, больше половины были мальчики. Больше трети мальчиков звали Федя. Всего среди гостей было три Феди. Какое наибольшее количество детей могло быть в гостях у Нади?","choices":["12","13","14","15","16"]},"22":{"question":"У Васи есть 7 доминошек, которые изображены на рисунке. Он хочет выложить их в линию, следуя обычным правилам игры в домино (в соседних квадратах двух соседних доминошек должно быть одинаковое количество точек). Какое наибольшее количество доминошек может быть в такой линии?","choices":["3","4","5","6","7"],"image":"assets/legacy-conditions/2013/task-22.webp","imageWidth":857,"imageHeight":67},"23":{"question":"50 мальчиков и 36 девочек встали в круг, держась за руки. Ровно у 26 мальчиков соседка справа — девочка. У скольких мальчиков соседка слева — девочка?","choices":["10","14","24","26","36"]},"24":{"question":"Крошка Ру умеет писать только две цифры: 1 и 7. Он хочет написать несколько чисел, сумма которых равна 2013. Какое наименьшее количество чисел ему придется написать?","choices":["2","3","5","7","9"]},"25":{"question":"Из большого покрашенного куба Катя вырезала 4 маленьких кубика. Затем она сделала отпечатки всех покрашенных граней новой фигуры. Сколько из следующих пяти картинок у нее получилось?","choices":["1","2","3","4","5"],"image":"assets/legacy-conditions/2013/task-25.webp","imageWidth":956,"imageHeight":282},"26":{"question":"Какое наименьшее количество карточек с цифрами (по одной цифре на каждой) надо иметь, чтобы можно было выложить любые четыре различных числа от 1 до 300 одновременно? (Карточки с цифрой 6 можно использовать и для обозначения цифры 9.)","choices":["16","68","74","90","160"]}},"2014":{"1":{"question":"Боря выложил из одинаковых палочек слово КЕНГУРУ. Сколько букв сложены из 5 палочек?","choices":["2","3","4","5","6"],"image":"assets/legacy-conditions/2014/task-01.webp","imageWidth":433,"imageHeight":101},"2":{"question":"Как в математике называется число, которое вычитают?","choices":["вычтенное","вычитуемое","вычитываемое","вычитающееся","вычитаемое"]},"3":{"question":"Как выглядит центральная часть звезды, изображенной на рисунке справа?","image":"assets/legacy-conditions/2014/task-03.webp","imageWidth":946,"imageHeight":296},"4":{"question":"Во сколько раз 10 метров больше 1 мм?","choices":["100 000","10 000","1000","100","10"]},"5":{"question":"Аня хочет вставить цифру 3 в число 2014 так, чтобы получившееся пятизначное число было как можно меньше. Где она должна написать цифру 3?","choices":["перед цифрой 2","между цифрами 2 и 0","между цифрами 0 и 1","между цифрами 1 и 4","после цифры 4"]},"6":{"question":"Андрей написал правильный пример, а его младший брат заклеил бумажными кружочками все знаки действий. Получилось 1 ○ 6 ○ 1 ○ 2 ○ 4 = 6. В каком порядке могли стоять знаки в этом примере?","choices":["+ + − +","+ − − +","+ + + −","+ − + −","+ − − −"]},"7":{"question":"Паша бросает дротики в мишень, изображенную справа. Сколько очков он не мог набрать за два броска?","choices":["60","80","90","100","120"],"image":"assets/legacy-conditions/2014/task-07.svg","imageWidth":220,"imageHeight":216},"8":{"question":"Никита выписал числа от 1 до 31. На сколько больше он написал единиц, чем троек?","choices":["8","9","10","11","13"]},"9":{"question":"Прямоугольник согнули пополам по жирной линии. Какая цифра оказалась не закрытой закрашенным квадратиком?","choices":["1","3","6","7","8"],"image":"assets/legacy-conditions/2014/manual-09.webp","imageWidth":207,"imageHeight":164},"10":{"question":"Адам собрал меньше орехов, чем Мартин, но больше, чем Сьюзен. Дана собрала больше, чем Мартин, и меньше, чем Люси. Кто из них собрал больше всего орехов?","choices":["Люси","Мартин","Сьюзен","Дана","Адам"]},"11":{"question":"На планете Кенгуру один год состоит из 20 месяцев, а каждый месяц — из 6 недель. Четверть года у кенгурят каникулы. Сколько недель продолжаются каникулы?","choices":["5","6","10","24","30"]},"12":{"question":"Семеро детей сидят за круглым столом. Никакие два мальчика не сидят рядом, и никакие три девочки не сидят подряд. Сколько девочек за столом?","choices":["2","3","4","5","6"]},"13":{"question":"Алиса заметила, что два месяца подряд 20-е число приходилось на четверг. Какой день недели будет 20-го числа в следующем за ними месяце?","choices":["понедельник","вторник","среда","пятница","воскресенье"]},"14":{"question":"На рисунке справа AC = 12, BD = 15, CE = 11 и AB = DE. Чему равна длина CD?","choices":["7","8","10","11","23"],"image":"assets/legacy-conditions/2014/task-14.webp","imageWidth":272,"imageHeight":48},"15":{"question":"Квадрат разрезан на четыре части, как показано на рисунке. Какую фигуру нельзя составить из этих частей?","image":"assets/legacy-conditions/2014/task-15.webp","imageWidth":950,"imageHeight":297},"16":{"question":"Вася взял в школу 18 конфет. Три конфеты он съел по дороге. Каждый раз, когда Вася съедал конфету в школе, он угощал конфетой Машу или Дашу, причем три раза он угостил сразу обеих девочек. Все конфеты были съедены. Сколько конфет съел Вася?","choices":["7","8","9","10","11"]},"17":{"question":"В ребусе одинаковые буквы обозначают одинаковые цифры, а разные буквы — разные цифры. Известно, что цифры 0, 8 и 9 не использованы. Какая еще цифра не использована?","choices":["2","3","4","5","6"],"image":"assets/legacy-conditions/2014/task-17.svg","imageWidth":174,"imageHeight":220},"18":{"question":"Летом дети ездили на велосипедах с дачи на озеро. От дачи до озера 3 км. Игорь проезжал весь путь за 10 минут, Маша ехала в 2 раза дольше, а Аня ехала быстрее Маши, но медленнее Игоря. Какая скорость могла быть у Ани?","choices":["20 км/ч","18 км/ч","12 км/ч","9 км/ч","6 км/ч"]},"19":{"question":"После того, как в 7:00 прозвенел будильник, Вася стукнул по нему кулаком, и минутная стрелка стала двигаться в 12 раз быстрее, чем надо. Что покажет этот будильник в 7:55?","image":"assets/legacy-conditions/2014/task-19.webp","imageWidth":939,"imageHeight":155},"20":{"question":"У малыша Феди есть 10 красных кубиков, 15 синих и 30 зеленых. Он хочет построить из них башню так, чтобы любые два соседних кубика имели разный цвет. Сколько кубиков будет в самой высокой башне, которую сможет построить Федя?","choices":["30","32","50","51","55"]},"21":{"question":"Братец Кролик за день съедает или 9 морковок, или 2 кочана капусты, или 1 кочан капусты и 4 морковки. За неделю он съел 30 морковок. Сколько кочанов капусты он съел за эту неделю?","choices":["6","7","8","9","10"]},"22":{"question":"Какое наименьшее число клеток надо закрасить, чтобы в любом квадратике 2 × 2 на рисунке была хотя бы одна закрашенная клетка?","choices":["8","6","5","4","3"],"image":"assets/legacy-conditions/2014/task-22.svg","imageWidth":220,"imageHeight":220},"23":{"question":"Фрекен Бок поставила на стол 15 тарелок с булочками. На первой тарелке лежит одна булочка, на второй — две, на третьей — три, и так далее. Иногда в окно влетает Карлсон, выбирает несколько тарелок и съедает с каждой из них одинаковое количество булочек. За какое наименьшее число визитов Карлсон сможет съесть все булочки?","choices":["3","4","5","10","15"]},"24":{"question":"Какой кубик получится из данной развертки?","image":"assets/legacy-conditions/2014/task-24.webp","imageWidth":947,"imageHeight":212},"25":{"question":"Назовем трехзначное число удивительным, если оно делится на 3, а первая и последняя цифры у него одинаковы. Чему равна наименьшая разность между двумя удивительными числами?","choices":["12","15","21","30","51"]},"26":{"question":"На рисунке изображен план дома Кенги. Любые две соседние комнаты соединены дверью. Кенга хочет пройти из комнаты А в комнату В, не проходя ни через какую комнату более одного раза. Сколькими способами Кенга сможет это сделать?","choices":["24","36","81","144","288"],"image":"assets/legacy-conditions/2014/task-26.webp","imageWidth":242,"imageHeight":240}},"2015":{"1":{"question":"Незнайка писал слово КЕНГУРУ. У него получилось: Сколько букв он написал неправильно?","choices":["1","2","3","4","5"],"image":"assets/legacy-conditions/2015/task-01.webp","imageWidth":366,"imageHeight":66},"2":{"question":"Чему равна сумма двадцати сотен и пятнадцати?","choices":["35","215","2015","20015","200015"]},"3":{"question":"Индеец Белый Орёл живет в вигваме, на котором треугольников и квадратиков нарисовано поровну. На каком из рисунков изображён его вигвам?","image":"assets/legacy-conditions/2015/task-03.webp","imageWidth":922,"imageHeight":187},"4":{"question":"Что не равно 12?","choices":["дюжина","число месяцев в году","число часов в сутках","утроенный номер этой задачи","число подвигов Геракла"]},"5":{"question":"На рисунке изображён пруд и несколько лягушек. Сколько из этих лягушек сидят в пруду?","choices":["5","6","7","8","9"],"image":"assets/legacy-conditions/2015/task-05.webp","imageWidth":343,"imageHeight":267},"6":{"question":"В числе 2015 четыре цифры. Произведение двух бóльших цифр поделили на сумму двух меньших. Что получилось?","choices":["6","7","8","10","15"]},"7":{"question":"Петя катается на велосипеде по дорожкам, изображённым на рисунке. Он стартует из точки О в направлении, указанном стрелкой. На первом перекрёстке Петя поворачивает направо, на втором — налево, потом опять направо, потом опять налево, и так далее. В какой точке он не может оказаться?","choices":["А","Б","В","Г","Д"],"image":"assets/legacy-conditions/2015/task-07.webp","imageWidth":332,"imageHeight":287},"8":{"question":"Аня отметила на прямой линии 5 красных точек. В каждый промежуток между красными точками она поставила синюю точку, а потом в каждый промежуток между красной и синей точками — зелёную точку. Сколько всего точек получилось?","choices":["9","15","17","18","20"]},"9":{"question":"Аня, Боря, Вася, Гриша и Дима написали на доске числа 1, 3, 4, 6 и 8, каждый по одному числу. Васино число оказалось в 2 раза больше, чем Димино, а Борино — на 2 больше, чем Гришино. Какое число написала Аня?","choices":["8","6","4","3","1"]},"10":{"question":"Тысяча дециметров равна","choices":["10 км","1 км","100 м","10 м","1 м"]},"11":{"question":"С первого января 2015 года малыш Федя начал вести дневник. Он уверен, что в каждом месяце ровно 30 дней. Какую дату он напишет в своем дневнике 19 марта 2015 года в день конкурса «Кенгуру»?","choices":["17 марта","18 марта","19 марта","20 марта","21 марта"]},"12":{"question":"Маша хочет разрезать по сторонам клеточек прямоугольник 4×3 так, чтобы из полученных частей можно было сложить фигурку, изображённую справа. На какое наименьшее число частей придётся разрезать прямоугольник?","choices":["2","3","4","5","6"],"image":"assets/legacy-conditions/2015/task-12.svg","imageWidth":220,"imageHeight":219},"13":{"question":"Вася наклеил на лист бумаги одну за другой 5 круглых наклеек с цифрами. В каком порядке он не мог их наклеивать?","choices":["3, 2, 5, 4, 1","5, 3, 4, 2, 1","3, 5, 1, 2, 4","5, 3, 2, 4, 1","3, 2, 1, 5, 4"],"image":"assets/legacy-conditions/2015/task-13.webp","imageWidth":313,"imageHeight":86},"14":{"question":"Друзья выясняли, какой сегодня день недели. Витя сказал: «Вчера было воскресенье». Сема сказал: «Завтра будет суббота». Петя сказал: «Позавчера была пятница». Саша сказал: «Послезавтра будет среда». Двое из них ошиблись. Какой сегодня день недели?","choices":["понедельник","вторник","среда","четверг","суббота"]},"15":{"question":"Какой из результатов самый маленький?","choices":["(100 − 1): 9","(1000 − 10): 9","(1000 − 1): 9","(1000 − 100): 9","(100 − 10): 9"]},"16":{"question":"Наташа рассматривает в лупу разные части рисунка на школьной доске. Какое из изображений А–Д она не сможет увидеть?","image":"assets/legacy-conditions/2015/task-16.webp","imageWidth":958,"imageHeight":223},"17":{"question":"Разность двух чисел на 3 меньше уменьшаемого и на 4 больше вычитаемого. Чему она равна?","choices":["7","9","10","12","15"]},"18":{"question":"Фигуру, изображённую на рис. 1, Вася разрезал на одинаковые треугольники, изображённые на рис. 2. Сколько треугольников у него получилось?","choices":["8","12","14","15","16"],"image":"assets/legacy-conditions/2015/task-18.webp","imageWidth":381,"imageHeight":197},"19":{"question":"Стрелочки на рисунке указывают на результаты действий с числами. Числа 1, 2, 3, 4, 5, 6 и 7 надо разместить по одному в квадратиках так, чтобы все результаты были правильными. Какое число попадёт в заштрихованный квадратик?","choices":["1","2","3","4","5"],"image":"assets/legacy-conditions/2015/task-19.webp","imageWidth":259,"imageHeight":208},"20":{"question":"Фигура на рисунке состоит из одинаковых квадратов со стороной 1 см. Чему равен её периметр?","choices":["9 см","10 см","11 см","12 см","невозможно определить"],"image":"assets/legacy-conditions/2015/task-20.svg","imageWidth":220,"imageHeight":217},"21":{"question":"Маша заполняет горшочек крупой. Он будет полным, если в него насыпать 6 чайных ложек, 3 десертных и 1 столовую ложку крупы или 2 чайные ложки, 1 десертную и 3 столовые ложки той же крупы. У Маши есть только столовые ложки. Сколько таких ложек крупы ей придется насыпать?","choices":["4","5","6","7","8"]},"22":{"question":"У длинной верёвки связали концы и разложили получившуюся петлю на столе. Часть этой петли закрыта (смотри рисунок). Как может выглядеть закрытая часть?","image":"assets/legacy-conditions/2015/task-22.webp","imageWidth":963,"imageHeight":305},"23":{"question":"В гостях у бабушки Женя и Лена ели мороженое ежедневно: каждая по 2 или 3 стаканчика. Всего Женя съела 25 стаканчиков, а Лена — 19. Сколько дней они гостили у бабушки?","choices":["8","9","10","11","12"]},"24":{"question":"В числовом ребусе буквами O, D, E, V, N обозначены разные цифры. Сколько различных цифр может обозначать буква V?","choices":["1","2","3","4","5"],"image":"assets/legacy-conditions/2015/task-24.svg","imageWidth":209,"imageHeight":220},"25":{"question":"Дима, Федя, Надя и Катя пошли в лес за грибами. Известно, что Дима нашел грибов меньше, чем Федя, мальчики нашли грибов столько же, сколько девочки, а Дима и Надя нашли грибов больше, чем Федя и Катя. Кто нашел больше всех грибов?","choices":["Дима","Федя","Катя","Надя","невозможно определить"]},"26":{"question":"Никита выписывает подряд целые числа 1, 2, 3,…, но он не любит цифру 7 и пропускает все числа, которые её содержат. Он выписал 777 чисел. Какое число он написал последним?","choices":["888","1000","1053","1333","1631"]}},"2016":{"1":{"question":"Кенга посмотрела на себя в зеркало. Что она увидела?","image":"assets/legacy-conditions/2016/task-01.webp","imageWidth":934,"imageHeight":315},"2":{"question":"Крошке Ру 17 марта исполняется 7 недель и 3 дня. Когда ему исполнится 9 недель?","choices":["21 марта","24 марта","26 марта","28 марта","30 марта"]},"3":{"question":"Какое число должно стоять в закрашенном квадратике?","choices":["72","56","40","32","20"],"image":"assets/legacy-conditions/2016/task-03.webp","imageWidth":258,"imageHeight":191},"4":{"question":"Дима с папой пришли в цирк и ищут свои места с номерами 86 и 87. По какой стрелке им надо идти?","image":"assets/legacy-conditions/2016/task-04.webp","imageWidth":964,"imageHeight":194},"5":{"question":"Когда Саша зашифровала цифры буквами, оказалось, что 65832 = КЕНГА. Какое из следующих зашифрованных чисел самое маленькое?","choices":["АГ","ЕК","НЕ","КА","ГА"]},"6":{"question":"Часть квадрата скрыта за шторкой. Какую форму имеет скрытая часть?","choices":["треугольник","четырехугольник","пятиугольник","шестиугольник","семиугольник"],"image":"assets/legacy-conditions/2016/task-06.webp","imageWidth":240,"imageHeight":231},"7":{"question":"Четвертое число в третьем десятке — это","choices":["43","34","32","24","23"]},"8":{"question":"Фигуры на рисунке — это круги, треугольники и квадраты. Что верно?","choices":["Кругов больше, чем квадратов.","Квадратов больше, чем треугольников.","Кругов в два раза больше, чем треугольников.","Треугольников в два раза больше, чем кругов.","Кругов меньше, чем треугольников."],"image":"assets/legacy-conditions/2016/task-08.svg","imageWidth":226,"imageHeight":205},"9":{"question":"Значок весит 3 г. Сколько весит тысяча таких значков?","choices":["30г","300 г","3 кг","30 кг","300 кг"]},"10":{"question":"Среди этих четырех карточек есть две одинаковые. Какие?","choices":["1 и 4","1 и 3","1 и 2","2 и 3","3 и 4"],"image":"assets/legacy-conditions/2016/task-10.webp","imageWidth":774,"imageHeight":109},"11":{"question":"Во дворе гуляют несколько собак. У этих собак лап на 18 больше, чем носов. Сколько собак во дворе?","choices":["4","5","6","8","9"]},"12":{"question":"Карточку, изображенную справа, перевернули сначала через левый край, а потом — через верхний край. Что получилось?","image":"assets/legacy-conditions/2016/task-12.webp","imageWidth":978,"imageHeight":324},"13":{"question":"Сумма двух чисел равна 170. Первое число оканчивается цифрой 5, а если эту цифру стереть, то получится второе число. Чему равна разность этих чисел?","choices":["110","120","130","140","150"]},"14":{"question":"Улитке нужно было проползти 12 метров. Утром до обеда она проползла 12 дм, а после обеда устала и проползла только 12 см. Какое расстояние ей осталось проползти?","choices":["1028 см","1068 см","102 дм","10 м","11 м"]},"15":{"question":"Когда число увеличили на 3, его последняя цифра уменьшилась. На сколько?","choices":["на 7","на 6","на 3","на 1","ответ зависит от числа"]},"16":{"question":"В некотором году тринадцатое января было вторником. Каким числом в том же месяце был первый понедельник после первого вторника?","choices":["5","7","12","14","19"]},"17":{"question":"Крошка Ру хочет пройти из комнаты А в комнату В (см. рисунок). Через какое наименьшее количество дверей ему придется пройти?","choices":["3","4","5","6","7"],"image":"assets/legacy-conditions/2016/task-17.svg","imageWidth":235,"imageHeight":234},"18":{"question":"Самое маленькое из двузначных чисел с двузначной суммой цифр сложили с самым большим из двузначных чисел с однозначной суммой цифр. Что получилось?","choices":["90","100","105","109","110"]},"19":{"question":"На рисунке изображено пять стопок картонных карточек. В каждой стопке три карточки: треугольная, круглая и квадратная. В скольких стопках треугольная карточка лежит выше квадратной?","choices":["1","2","3","4","5"],"image":"assets/legacy-conditions/2016/task-19.webp","imageWidth":733,"imageHeight":116},"20":{"question":"Каждую звездочку в примере 2 * 2 * 2 можно заменить на один из знаков арифметического действия. Какой результат нельзя получить?","choices":["1","2","3","6","все результаты А–Г можно получить"]},"21":{"question":"Электронные часы показывают часы и минуты. Например, в 6 часов утра они показывают 06:00, а в 6 часов вечера — 18:00. Сколько минут за сутки на табло часов будут видны ровно три нуля?","choices":["26","25","24","23","12"]},"22":{"question":"Пять различных точек А, В, С, D и Е расположены на прямой так, что АВ = 6, АD = 2, АЕ = 2, СЕ = 4. Какие две точки крайние?","choices":["В и С","С и D","А и D","Е и D","невозможно определить"]},"23":{"question":"Аня хочет вписать числа в пустые кружочки так, чтобы на всех сторонах пятиугольника суммы трех чисел были одинаковы. Какое число она должна вписать в закрашенный кружочек?","choices":["9","10","13","23","40"],"image":"assets/legacy-conditions/2016/task-23.svg","imageWidth":230,"imageHeight":221},"24":{"question":"Большой куб 4 × 4 × 4 сложен из 64 маленьких кубиков, один из которых красный, а остальные — белые (см. рисунок). По взмаху волшебной палочки каждый белый кубик, имеющий общую грань с красным кубиком, тоже становится красным. Сколько будет красных кубиков после трех взмахов волшебной палочки?","choices":["27","32","33","48","64"],"image":"assets/legacy-conditions/2016/task-24.webp","imageWidth":237,"imageHeight":237},"25":{"question":"Два трехзначных числа составлены из шести различных цифр так, что первая цифра второго числа вдвое больше, чем последняя цифра первого числа. Какова наименьшая возможная сумма таких чисел?","choices":["597","588","546","537","535"]},"26":{"question":"Четыре одинаковых игральных кубика (общее число точек на противоположных гранях равно 7) приложили друг к другу одинаковыми гранями и закрасили некоторые грани (см. рисунок). Какое самое маленькое число точек могло быть закрашено на трех верхних гранях?","choices":["3","4","5","6","7"],"image":"assets/legacy-conditions/2016/task-26.webp","imageWidth":272,"imageHeight":144}},"2017":{"1":{"question":"Кенга составила пять примеров на сложение. Какая сумма самая большая?","choices":["2 + 0 + 1 + 7","2 + 0 + 17","20 + 17","20 + 1 + 7","201 + 7"]},"2":{"question":"Ярик отметил стрелочками на схеме путь от дома до озера. Сколько стрелочек он нарисовал неправильно?","choices":["3","4","5","7","10"],"image":"assets/legacy-conditions/2017/task-02.webp","imageWidth":518,"imageHeight":105},"3":{"question":"Число 100 увеличили в полтора раза, а результат уменьшили в два раза. Что получилось?","choices":["150","100","75","50","25"]},"4":{"question":"На рисунке справа изображены бусы. На каком рисунке изображены те же бусы?","image":"assets/legacy-conditions/2017/task-04.webp","imageWidth":959,"imageHeight":294},"5":{"question":"Женя составила шесть трехзначных чисел из цифр 2, 5 и 7 (цифры в каждом числе различны). Потом она расположила эти числа в порядке возрастания. Какое число оказалось третьим?","choices":["257","527","572","752","725"]},"6":{"question":"На рисунке изображены три квадрата, разбитых на клетки. На крайних квадратах часть клеток закрашена, а остальные — прозрачные. Оба эти квадрата наложили на средний квадрат так, что их верхние левые углы совпали. Какая из фигурок осталась видна?","image":"assets/legacy-conditions/2017/task-06.webp","imageWidth":968,"imageHeight":292},"7":{"question":"Какое самое маленькое число белых клеток на рисунке надо закрасить, чтобы закрашенных клеток стало больше, чем белых?","choices":["1","2","3","4","5"],"image":"assets/legacy-conditions/2017/task-07.webp","imageWidth":224,"imageHeight":141},"8":{"question":"Маша нарисовала 30 геометрических фигур в таком порядке: треугольник, круг, квадрат, ромб, потом снова треугольник, круг, квадрат, ромб и так далее. Сколько треугольников нарисовала Маша?","choices":["5","6","7","8","9"]},"9":{"question":"Спереди дом выглядит так, как изображено на рисунке справа. Сзади у этого дома есть дверь и два окна. Как он выглядит сзади?","image":"assets/legacy-conditions/2017/task-09.webp","imageWidth":964,"imageHeight":315},"10":{"question":"Сейчас 2017 год. Через сколько лет будет ближайший год, в записи которого нет цифры 0?","choices":["100","95","94","84","83"]},"11":{"question":"Шарики продаются упаковками по 5, 10 или 25 штук в каждой. Аня хочет купить ровно 70 шариков. Какое самое маленькое число упаковок ей придется купить?","choices":["3","4","5","6","7"]},"12":{"question":"Миша сложил квадратный лист бумаги и проткнул в нём дырку. Потом он развернул лист и увидел то, что изображено на рисунке справа. Как могли выглядеть линии сгиба?","image":"assets/legacy-conditions/2017/task-12.webp","imageWidth":964,"imageHeight":282},"13":{"question":"Три черепахи сидят на дорожке в точках A, B и C (см. рисунок). Они решили собраться в одной точке и найти сумму пройденных ими расстояний. Какая самая маленькая сумма могла у них получиться?","choices":["8 м","10 м","12 м","13 м","18 м"],"image":"assets/legacy-conditions/2017/task-13.webp","imageWidth":331,"imageHeight":87},"14":{"question":"В промежутки между цифрами 1 6 3 1 7 надо вставить два знака + и два знака × так, чтобы получился самый большой результат. Чему он равен?","choices":["16","18","26","28","126"]},"15":{"question":"Полоска на рисунке составлена из 10 квадратиков со стороной 1. Сколько таких же квадратиков надо приложить к ней справа, чтобы периметр полоски стал в два раза больше?","choices":["9","10","11","12","20"],"image":"assets/legacy-conditions/2017/task-15.webp","imageWidth":445,"imageHeight":61},"16":{"question":"В клетчатом квадрате Саша отметила клетку. Оказалось, что в своем столбце эта клетка четвертая снизу и пятая сверху. Кроме того, в своей строке эта клетка шестая слева. Какая она справа?","choices":["вторая","третья","четвертая","пятая","шестая"]},"17":{"question":"Из прямоугольника 4 × 3 Федя вырезал две одинаковые фигурки. Какого вида фигурки у него не могли получиться?","image":"assets/legacy-conditions/2017/task-17.webp","imageWidth":971,"imageHeight":344},"18":{"question":"Каждый из трех мальчиков загадал по два числа от 1 до 10. Все шесть чисел оказались различными. Сумма чисел у Андрея — 4, у Бори — 7, у Вити — 10. Тогда одно из Витиных чисел — это","choices":["1","2","3","5","6"]},"19":{"question":"В клетках квадрата 4 × 4 расставлены числа. Соня нашла квадратик 2 × 2, в котором сумма чисел самая большая. Чему равна эта сумма?","choices":["11","12","13","14","15"],"image":"assets/legacy-conditions/2017/task-19.webp","imageWidth":188,"imageHeight":187},"20":{"question":"Дима катался на велосипеде по дорожкам парка. Он въехал в парк в ворота А. Во время прогулки он три раза поворачивал направо, четыре раза налево и один раз разворачивался. Через какие ворота он выехал?","choices":["А","Б","В","Г","ответ зависит от порядка поворотов"],"image":"assets/legacy-conditions/2017/task-20.webp","imageWidth":280,"imageHeight":276},"21":{"question":"В забеге участвовало несколько детей. Число прибежавших раньше Миши в три раза больше числа тех, кто прибежал после него. А число прибежавших раньше Саши в два раза меньше, чем число прибежавших после нее. Сколько детей могло участвовать в забеге?","choices":["21","22","23","24","25"]},"22":{"question":"В некоторых закрашенных клетках спрятано по одному цветочку. В каждой белой клетке написано количество клеток с цветочками, которые имеют с ней общую сторону или вершину. Сколько цветочков спрятано?","choices":["4","5","6","7","11"],"image":"assets/legacy-conditions/2017/task-22.webp","imageWidth":186,"imageHeight":187},"23":{"question":"Трехзначное число назовем удивительным, если среди шести цифр, которыми записывается оно и следующее за ним число, есть ровно три единицы и ровно одна девятка. Сколько всего удивительных чисел?","choices":["0","1","2","3","4"]},"24":{"question":"Каждая грань куба разделена на девять квадратиков (см. рисунок). Какое самое большое число квадратиков можно покрасить, чтобы никакие два покрашенных квадратика не имели общей стороны?","choices":["16","18","20","22","30"],"image":"assets/legacy-conditions/2017/task-24.webp","imageWidth":193,"imageHeight":165},"25":{"question":"Стопка карточек с дырками нанизана на нитку (см. рисунок справа). Каждая карточка с одной стороны белая, а с другой — закрашенная. Вася разложил карточки на столе. Что у него могло получиться?","image":"assets/legacy-conditions/2017/task-25.webp","imageWidth":964,"imageHeight":380},"26":{"question":"Из аэропорта на автовокзал через каждые три минуты отправляется автобус, который едет 1 час. Через 2 минуты после отправления автобуса из аэропорта выехал автомобиль и ехал до автовокзала 35 минут. Сколько автобусов он обогнал?","choices":["12","11","10","8","7"]}},"2018":{"1":{"question":"Сколько различных цифр в записи даты конкурса «Кенгуру» 15.03.2018?","choices":["5","6","7","8","10"]},"2":{"question":"Сколько раз пересекаются сплошная и пунктирная линии?","choices":["6","7","8","9","10"],"image":"assets/legacy-conditions/2018/task-02.webp","imageWidth":286,"imageHeight":202},"3":{"question":"В Петербурге 15 марта в 16 часов пошел снег, а 16 марта в 15 часов снегопад закончился. Сколько часов он продолжался?","choices":["11","12","23","24","25"]},"4":{"question":"На одном из рисунков А–Д божья коровка отличается от других четырех. На каком?","image":"assets/legacy-conditions/2018/task-04.webp","imageWidth":925,"imageHeight":151},"5":{"question":"На рисунке изображен план парка с семью аллеями. Маша вышла из точки O и прошла по двум аллеям. В какой точке она не могла оказаться?","choices":["А","Б","В","Г","Д"],"image":"assets/legacy-conditions/2018/task-05.svg","imageWidth":261,"imageHeight":193},"6":{"question":"Тимур вырезал из клетчатой бумаги несколько четырехугольников двух видов (см. рисунок). Сколько четырехугольников ему надо взять, чтобы сложить кораблик?","choices":["5","6","7","8","9"],"image":"assets/legacy-conditions/2018/task-06.webp","imageWidth":366,"imageHeight":205},"7":{"question":"Чему равна сумма наибольшей и наименьшей из тех цифр, которых нет в записи числа 2018?","choices":["7","9","10","12","15"]},"8":{"question":"Миша склеил конструкцию из 10 белых кубиков. Потом он покрасил ее со всех сторон. Сколько кубиков имеют ровно 4 окрашенные грани?","choices":["6","7","8","9","10"],"image":"assets/legacy-conditions/2018/task-08.svg","imageWidth":223,"imageHeight":193},"9":{"question":"Четыре шурупа на рисунке имеют одинаковую длину, а один короче остальных. Какой?","choices":["1","2","3","4","5"],"image":"assets/legacy-conditions/2018/manual-09.webp","imageWidth":206,"imageHeight":217},"10":{"question":"В примере на вычитание двузначных чисел Оля закрасила две цифры. Чему равно произведение закрашенных цифр?","choices":["6","7","8","9","10"],"image":"assets/legacy-conditions/2018/task-10.webp","imageWidth":362,"imageHeight":84},"11":{"question":"Даня стрелял из лука по мишени. В первый раз он набрал 12 очков, во второй — 15 очков. Сколько очков он набрал в третий раз?","image":"assets/legacy-conditions/2018/task-11.webp","imageWidth":962,"imageHeight":214},"12":{"question":"Если середина первой половины июня — среда, то середина второй половины июня того же года — это","choices":["понедельник","вторник","четверг","пятница","суббота"]},"13":{"question":"У Алика есть много наклеек пяти разных видов. Он вклеивает их по одной в каждую клетку квадрата так, чтобы фигурки в каждом столбце и в каждой строчке не повторялись. Какая наклейка должна оказаться в закрашенной клетке?","image":"assets/legacy-conditions/2018/task-13.webp","imageWidth":960,"imageHeight":230},"14":{"question":"У Ани есть два младших брата-близнеца. Они родились в тот день, когда Ане исполнилось 8 лет. Сколько лет ей исполнится, когда ее возраст станет равен сумме возрастов близнецов?","choices":["12","14","16","18","20"]},"15":{"question":"Прямоугольник состоит из пяти квадратов. Три маленьких квадрата имеют сторону, равную 1 см. Чему равен периметр прямоугольника?","choices":["11 см","22 см","24 см","28 см","32 см"],"image":"assets/legacy-conditions/2018/task-15.webp","imageWidth":241,"imageHeight":145},"16":{"question":"Чему равна сумма двух чисел, если она на шесть больше одного из них и в три раза больше другого?","choices":["9","12","16","18","24"]},"17":{"question":"В каждой клетке доски записано число (см. рисунок). Жук Жак заполз на клетку доски с числом 1. Потом он добрался до нижнего ряда, переползая каждый раз через сторону клетки так, чтобы число в новой клетке было больше числа в предыдущей. В клетке с каким числом он оказался?","choices":["12","14","6","10","9"],"image":"assets/legacy-conditions/2018/task-17.svg","imageWidth":229,"imageHeight":229},"18":{"question":"Федя время от времени смотрит на часы, висящие на стене, и записывает, куда указывает секундная стрелка. У него получился такой список: вверх, влево, вниз, вверх, вверх. Какое наименьшее время могло пройти между первой и последней записями?","choices":["2 мин","2 мин 15 сек","2 мин 45 сек","3 мин","4 мин"]},"19":{"question":"Четыре гирьки, которые весят 10 г, 20 г, 30 г и 40 г, взвешивали на чашечных весах (см. рисунок). Сколько весит гирька С?","choices":["10 г","20 г","30 г","40 г","невозможно определить"],"image":"assets/legacy-conditions/2018/task-19.webp","imageWidth":457,"imageHeight":171},"20":{"question":"Вася, Коля, Митя и Петя взяли синий, красный, желтый и зеленый мячи, каждый по одному. — У меня мяч не красный, — сказал Вася. — У меня мяч не синий, — сказал Петя. — У меня мяч не зеленый, — сказал Коля. — У меня мяч не желтый и не синий, — сказал Митя. Соврал только тот, у кого красный мяч. Какой мяч у Коли?","choices":["синий","красный","зеленый","желтый","невозможно определить"]},"21":{"question":"В комнате находятся три котенка и два утенка, а во дворе — один котенок и три утенка. Шесть лап перебежали из комнаты в кухню, а потом восемь лап прибежали со двора в комнату. Сколько утят стало в комнате?","choices":["1","2","3","4","5"]},"22":{"question":"В числах 345 и 921 выбрали по одной цифре и поменяли их местами друг с другом. При этом сумма чисел увеличилась. Чему стала равна эта сумма?","choices":["1267","1293","1295","1300","1464"]},"23":{"question":"Путь от дома Пятачка до дома Винни-Пуха равен 160 м, от дома Винни-Пуха до дома Совы 200 м, а от дома Совы до дома Кролика 190 м. Мост через реку имеет длину 10 м. Сколько метров от домика Пятачка до домика Кролика?","choices":["130","140","160","170","180"],"image":"assets/legacy-conditions/2018/task-23.webp","imageWidth":466,"imageHeight":296},"24":{"question":"Дима придумал способ выкладывать цифры спичками: Потом, используя 17 спичек, он выложил самое большое возможное число. Какова будет первая цифра этого числа?","choices":["1","2","7","8","9"],"image":"assets/legacy-conditions/2018/task-24.webp","imageWidth":981,"imageHeight":165},"25":{"question":"В ребусе одинаковые цифры зашифрованы одинаковыми буквами, а разные — разными. Известно, что ДОМ = 256. Одна цифра в ребусе не использована. Какая?","choices":["0","3","4","7","9"],"image":"assets/legacy-conditions/2018/task-25.svg","imageWidth":220,"imageHeight":216},"26":{"question":"Сколько всего квадратов, образованных жирными линиями, изображено на рисунке?","choices":["16","20","23","24","25"],"image":"assets/legacy-conditions/2018/task-26.svg","imageWidth":220,"imageHeight":219}},"2019":{"1":{"question":"В зоопарке 21 ноября 2018 года родился кенгуренок. Сколько месяцев ему исполнилось 21 марта 2019 года?","choices":["3","4","5","6","7"]},"2":{"question":"Для награждения победителей соревнования сделали пьедестал: чем лучше результат участника, тем выше ступенька, на которой он стоит. Участник с каким номером занял третье место?","choices":["5","6","7","8","9"],"image":"assets/legacy-conditions/2019/manual-02.webp","imageWidth":307,"imageHeight":225},"3":{"question":"Индейцы майя записывали числа с помощью точек и отрезков. Число пять изображалось отрезком, а единица — точкой. Например, первый рисунок изображал число 8. Какое число изображалось вторым рисунком?","choices":["7","12","15","19","22"],"image":"assets/legacy-conditions/2019/manual-03.webp","imageWidth":142,"imageHeight":34},"4":{"question":"Какой из кусочков А–Д можно вырезать из квадрата, изображенного справа?","image":"assets/legacy-conditions/2019/task-04.webp","imageWidth":960,"imageHeight":246},"5":{"question":"Если вчера была суббота, то какой день недели будет послезавтра?","choices":["вторник","среда","пятница","суббота","воскресенье"]},"6":{"question":"Через какую точку придется пройти Винни-Пуху, чтобы, двигаясь по стрелочкам, попасть в гости к Пятачку?","choices":["А","Б","В","Г","Д"],"image":"assets/legacy-conditions/2019/task-06.svg","imageWidth":375,"imageHeight":268},"7":{"question":"Сколько из нарисованных ниже фигур можно получить, если отрезать одну клетку от фигуры, изображенной справа?","choices":["одну","две","три","четыре","пять"],"image":"assets/legacy-conditions/2019/task-07.webp","imageWidth":968,"imageHeight":201},"8":{"question":"Какое из следующих чисел самое маленькое?","choices":["500005","50050","500050","50005","55000"]},"9":{"question":"Какую из фигур А–Д нельзя сложить из 10 спичек?","image":"assets/legacy-conditions/2019/task-09.webp","imageWidth":963,"imageHeight":363},"10":{"question":"Из цифр 2, 0, 1, 9, используя каждую только один раз, можно составить некоторые даты (число и месяц), например, 09.12. Маша обнаружила, что из этих цифр можно составить день ее рождения. Она родилась в октябре. Какого числа она родилась?","choices":["10","12","19","20","29"]},"11":{"question":"Женя выписала все трехзначные числа, у каждого из которых первая цифра равна 4, все цифры различны и расположены в порядке убывания. Сколько чисел выписала Женя?","choices":["1","3","4","6","16"]},"12":{"question":"На рисунке изображена открытая книжка. В ее обложке два окошка. Какие три фигурки будут видны, если книжку закрыть?","image":"assets/legacy-conditions/2019/task-12.webp","imageWidth":886,"imageHeight":257},"13":{"question":"В аквариуме 15 рыбок: барбусы, меченосцы и сомики. Известно, что 10 из них — не сомики, а 9 — не барбусы. Сколько меченосцев в аквариуме?","choices":["1","2","3","4","5"]},"14":{"question":"У Миши есть 6 доминошек, которые изображены на рисунке справа. Он выложил их в линию, следуя обычным правилам игры в домино (число точек в соседних квадратиках двух разных доминошек всегда одинаково). В первом квадратике слева стоит одна точка. Сколько точек в самом правом квадратике?","choices":["1","2","3","4","5"],"image":"assets/legacy-conditions/2019/task-14.webp","imageWidth":965,"imageHeight":262},"15":{"question":"В классе 5 человек изучают китайский язык и 6 человек — японский. Всего в классе изучают эти языки 8 человек. Сколько человек изучают оба этих языка?","choices":["5","4","3","2","1"]},"16":{"question":"На рисунке одинаковые значки обозначают одинаковые числа, а разные значки — разные числа. Сумма чисел, стоящих в строчке, написана справа от нее. Какое число обозначено значком ★?","choices":["2","3","4","5","6"],"image":"assets/legacy-conditions/2019/manual-16.webp","imageWidth":192,"imageHeight":154},"17":{"question":"У одного из пяти мальчиков есть футбольный мяч. Алеша сказал: «У меня нет мяча». Боря сказал: «Мяч у меня». Витя сказал: «Мяч не у Дани». Гоша сказал: «У меня нет мяча». Даня сказал: «Мяч у Алеши». Только один мальчик сказал неправду. Кто?","choices":["Алеша","Боря","Витя","Гоша","Даня"]},"18":{"question":"В числе 2019 две цифры поменяли местами, а потом одну цифру стерли. Какое самое большое число могло получиться?","choices":["901","910","912","920","921"]},"19":{"question":"Все три гномика на рисунке весят одинаково. Вес гномика — целое число килограммов. Сколько весит гномик?","choices":["3 кг","4 кг","5 кг","6 кг","8 кг"],"image":"assets/legacy-conditions/2019/task-19.webp","imageWidth":568,"imageHeight":202},"20":{"question":"Все страницы в книге пронумерованы. Цифра 5 встречается в номерах страниц ровно 13 раз. Сколько страниц в этой книге?","choices":["50","56","57","58","60"]},"21":{"question":"Шнурок продет через дырки в дощечке, как показано на рисунке справа. Как может выглядеть эта дощечка с обратной стороны?","image":"assets/legacy-conditions/2019/task-21.webp","imageWidth":985,"imageHeight":337},"22":{"question":"Назовем двузначное число супердвузначным, если и при умножении его на 2, и при делении его на 2 снова получается двузначное число. Сколько всего супердвузначных чисел?","choices":["15","16","18","20","25"]},"23":{"question":"На рисунке изображен коридор и указаны некоторые размеры. Кот прошел вдоль пунктирной линии, точно по середине коридора. Сколько метров прошел кот?","choices":["63 м","68 м","69 м","71 м","83 м"],"image":"assets/legacy-conditions/2019/task-23.webp","imageWidth":419,"imageHeight":205},"24":{"question":"В вершины куба на рисунке Женя вписала числа от 1 до 8, каждое по одному разу. Для каждой из шести граней она нашла сумму четырех чисел, написанных в вершинах этой грани. Три из этих сумм — это 16, 18 и 22. Чему равна самая маленькая из всех шести сумм?","choices":["10","12","14","15","16"],"image":"assets/legacy-conditions/2019/task-24.webp","imageWidth":236,"imageHeight":237},"25":{"question":"Малыш, Карлсон и фрекен Бок едят плюшки. Малыш съедает 2 плюшки за то же время, за которое фрекен Бок съедает 7. Пока она ест 3 плюшки, Карлсон съедает 5. За некоторое время Малыш и фрекен Бок съели 27 плюшек. Сколько плюшек за это время съел Карлсон?","choices":["10","15","35","40","45"]},"26":{"question":"В клетки квадрата на рисунке Вася хочет вписать числа от 1 до 5 так, чтобы в каждой строке и каждом столбце все числа были различны. Квадрат разбит на три области. Суммы чисел в областях должны быть равны. В левую нижнюю клетку Вася вписал число 2. Какое число он впишет в правую верхнюю клетку?","choices":["1","2","3","4","5"],"image":"assets/legacy-conditions/2019/task-26.svg","imageWidth":220,"imageHeight":220}}};
